begin;

alter table public.lesson_segment_notes
  add column if not exists stop_criterion text not null default '';

alter table public.lesson_segment_notes
  drop constraint if exists lesson_segment_notes_stop_criterion_length;
alter table public.lesson_segment_notes
  add constraint lesson_segment_notes_stop_criterion_length
  check (stop_criterion = '' or char_length(stop_criterion) between 10 and 2000);

create temporary table course_one_parts (
  block_position integer not null,
  segment_position integer not null,
  block_title text not null,
  title text not null,
  narration text not null,
  explanation text not null,
  key_points text[] not null,
  stop_criterion text not null,
  source_label text not null,
  source_pages text not null,
  audio_path_template text not null,
  duration_seconds integer not null,
  size_bytes bigint not null,
  primary key (block_position, segment_position)
) on commit drop;

insert into course_one_parts values
(1, 1, E'Definición de los trabajos y fases del movimiento de tierras', E'Introducción al movimiento de tierras en explotaciones', E'El movimiento de tierras reúne las operaciones necesarias para modificar el terreno en una explotación. El ciclo principal comprende el arranque, la carga, el transporte y la descarga, y puede completarse con extendido, nivelación, compactación y refino.', E'El movimiento de tierras reúne las operaciones necesarias para modificar el terreno en una explotación. El ciclo principal comprende el arranque, la carga, el transporte y la descarga, y puede completarse con extendido, nivelación, compactación y refino. En la aplicación práctica deben respetarse el manual del fabricante, las disposiciones internas de seguridad y el criterio de parada indicado.', array[E'El movimiento de tierras reúne las operaciones necesarias para modificar el terreno en una explotación', E'El ciclo principal comprende el arranque, la carga, el transporte y la descarga, y puede completarse con…', E'Aplicar el manual del fabricante y las disposiciones internas']::text[], E'Detenga la operación y comunique cualquier condición que impida trabajar con seguridad.', E'ET 2001-1-08 · Presentación Cursos Pedro · Manual, página PDF 13', E'13', E'{courseVersionId}/block-1/audio/part-1-01.mp4', 26, 424815),
(1, 2, E'Definición de los trabajos y fases del movimiento de tierras', E'La fase de arranque: concepto y objetivos principales', E'El arranque es la primera fase del ciclo. Su objetivo es separar el material del macizo o del terreno natural y dejarlo en condiciones adecuadas para su carga. El método depende de la naturaleza, dureza y estado del material.', E'El arranque es la primera fase del ciclo. Su objetivo es separar el material del macizo o del terreno natural y dejarlo en condiciones adecuadas para su carga. El método depende de la naturaleza, dureza y estado del material. En la aplicación práctica deben respetarse el manual del fabricante, las disposiciones internas de seguridad y el criterio de parada indicado.', array[E'El arranque es la primera fase del ciclo', E'Su objetivo es separar el material del macizo o del terreno natural y dejarlo en condiciones adecuadas para su…', E'El método depende de la naturaleza, dureza y estado del material']::text[], E'Detenga la operación y comunique cualquier condición que impida trabajar con seguridad.', E'ET 2001-1-08 · Presentación Cursos Pedro · Manual, página PDF 13', E'13', E'{courseVersionId}/block-1/audio/part-1-02.mp4', 18, 288718),
(1, 3, E'Definición de los trabajos y fases del movimiento de tierras', E'Métodos de arranque: uso de voladuras y perforación', E'Cuando la roca sana presenta elevada dureza, el arranque suele requerir perforación y voladura. La operación debe planificarse para obtener la fragmentación necesaria, limitar proyecciones y vibraciones y facilitar las fases posteriores.', E'Cuando la roca sana presenta elevada dureza, el arranque suele requerir perforación y voladura. La operación debe planificarse para obtener la fragmentación necesaria, limitar proyecciones y vibraciones y facilitar las fases posteriores. En la aplicación práctica deben respetarse el manual del fabricante, las disposiciones internas de seguridad y el criterio de parada indicado.', array[E'Cuando la roca sana presenta elevada dureza, el arranque suele requerir perforación y voladura', E'La operación debe planificarse para obtener la fragmentación necesaria, limitar proyecciones y vibraciones y…', E'Aplicar el manual del fabricante y las disposiciones internas']::text[], E'Detenga la operación y comunique cualquier condición que impida trabajar con seguridad.', E'ET 2001-1-08 · Presentación Cursos Pedro · Manual, página PDF 14', E'14', E'{courseVersionId}/block-1/audio/part-1-03.mp4', 17, 274941),
(1, 4, E'Definición de los trabajos y fases del movimiento de tierras', E'El arranque mecánico mediante tractor de cadenas y ripper', E'Los materiales ripables pueden arrancarse mecánicamente con un tractor de cadenas provisto de escarificador o ripper. La penetración de los dientes y el empuje del tractor rompen y aflojan el terreno sin recurrir a explosivos.', E'Los materiales ripables pueden arrancarse mecánicamente con un tractor de cadenas provisto de escarificador o ripper. La penetración de los dientes y el empuje del tractor rompen y aflojan el terreno sin recurrir a explosivos. En la aplicación práctica deben respetarse el manual del fabricante, las disposiciones internas de seguridad y el criterio de parada indicado.', array[E'Los materiales ripables pueden arrancarse mecánicamente con un tractor de cadenas provisto de escarificador o…', E'La penetración de los dientes y el empuje del tractor rompen y aflojan el terreno sin recurrir a explosivos', E'Aplicar el manual del fabricante y las disposiciones internas']::text[], E'Detenga la operación y comunique cualquier condición que impida trabajar con seguridad.', E'ET 2001-1-08 · Presentación Cursos Pedro · Manual, página PDF 14', E'14', E'{courseVersionId}/block-1/audio/part-1-04.mp4', 17, 274864),
(1, 5, E'Definición de los trabajos y fases del movimiento de tierras', E'La fase de carga: introducción y equipos habituales', E'La carga recoge el material arrancado y lo deposita en el equipo de transporte o en la instalación receptora. Entre los equipos habituales se encuentran la pala cargadora y la excavadora, seleccionadas según frente, producción y compatibilidad con el transporte.', E'La carga recoge el material arrancado y lo deposita en el equipo de transporte o en la instalación receptora. Entre los equipos habituales se encuentran la pala cargadora y la excavadora, seleccionadas según frente, producción y compatibilidad con el transporte. En la aplicación práctica deben respetarse el manual del fabricante, las disposiciones internas de seguridad y el criterio de parada indicado.', array[E'La carga recoge el material arrancado y lo deposita en el equipo de transporte o en la instalación receptora', E'Entre los equipos habituales se encuentran la pala cargadora y la excavadora, seleccionadas según frente,…', E'Aplicar el manual del fabricante y las disposiciones internas']::text[], E'Detenga la operación y comunique cualquier condición que impida trabajar con seguridad.', E'ET 2001-1-08 · Presentación Cursos Pedro · Manual, páginas PDF 13–14', E'13–14', E'{courseVersionId}/block-1/audio/part-1-05.mp3', 16, 276728),
(1, 6, E'Definición de los trabajos y fases del movimiento de tierras', E'Características operativas de la pala cargadora sobre ruedas', E'La pala cargadora sobre ruedas destaca por su movilidad, rapidez de desplazamiento y versatilidad en firmes adecuados. Su rendimiento exige controlar el estado del terreno, la estabilidad, los neumáticos y la posición segura del cucharón durante la circulación.', E'La pala cargadora sobre ruedas destaca por su movilidad, rapidez de desplazamiento y versatilidad en firmes adecuados. Su rendimiento exige controlar el estado del terreno, la estabilidad, los neumáticos y la posición segura del cucharón durante la circulación. En la aplicación práctica deben respetarse el manual del fabricante, las disposiciones internas de seguridad y el criterio de parada indicado.', array[E'La pala cargadora sobre ruedas destaca por su movilidad, rapidez de desplazamiento y versatilidad en firmes…', E'Su rendimiento exige controlar el estado del terreno, la estabilidad, los neumáticos y la posición segura del…', E'Aplicar el manual del fabricante y las disposiciones internas']::text[], E'Detenga la operación y comunique cualquier condición que impida trabajar con seguridad.', E'ET 2001-1-08 · Presentación Cursos Pedro · Manual, páginas PDF 14–15', E'14–15', E'{courseVersionId}/block-1/audio/part-1-06.mp3', 15, 260428),
(1, 7, E'Definición de los trabajos y fases del movimiento de tierras', E'Análisis de costes y distancias en la fase de transporte', E'El transporte suele tener un peso decisivo en el coste del movimiento de tierras. La distancia, las diferencias de cota, el estado y pendiente de las pistas, la capacidad del equipo y los tiempos de espera determinan el rendimiento del ciclo.', E'El transporte suele tener un peso decisivo en el coste del movimiento de tierras. La distancia, las diferencias de cota, el estado y pendiente de las pistas, la capacidad del equipo y los tiempos de espera determinan el rendimiento del ciclo. En la aplicación práctica deben respetarse el manual del fabricante, las disposiciones internas de seguridad y el criterio de parada indicado.', array[E'El transporte suele tener un peso decisivo en el coste del movimiento de tierras', E'La distancia, las diferencias de cota, el estado y pendiente de las pistas, la capacidad del equipo y los…', E'Aplicar el manual del fabricante y las disposiciones internas']::text[], E'Detenga la operación y comunique cualquier condición que impida trabajar con seguridad.', E'ET 2001-1-08 · Presentación Cursos Pedro · Manual, página PDF 13', E'13', E'{courseVersionId}/block-1/audio/part-1-07.mp3', 15, 261263),
(1, 8, E'Definición de los trabajos y fases del movimiento de tierras', E'Tipos de transporte y descarga en tolva o escombrera', E'El material puede transportarse con volquetes, dúmperes, camiones bañera u otros sistemas continuos. La descarga puede realizarse en tolvas, acopios o escombreras y requiere una zona estable, señalizada y compatible con el equipo.', E'El material puede transportarse con volquetes, dúmperes, camiones bañera u otros sistemas continuos. La descarga puede realizarse en tolvas, acopios o escombreras y requiere una zona estable, señalizada y compatible con el equipo. En la aplicación práctica deben respetarse el manual del fabricante, las disposiciones internas de seguridad y el criterio de parada indicado.', array[E'El material puede transportarse con volquetes, dúmperes, camiones bañera u otros sistemas continuos', E'La descarga puede realizarse en tolvas, acopios o escombreras y requiere una zona estable, señalizada y…', E'Aplicar el manual del fabricante y las disposiciones internas']::text[], E'Detenga la operación y comunique cualquier condición que impida trabajar con seguridad.', E'ET 2001-1-08 · Presentación Cursos Pedro · Manual, páginas PDF 14–17', E'14–17', E'{courseVersionId}/block-1/audio/part-1-08.mp3', 15, 262099),
(1, 9, E'Definición de los trabajos y fases del movimiento de tierras', E'Extendido, nivelación, compactación y refino', E'Después de la descarga pueden ser necesarias operaciones de extendido, nivelación, compactación y refino. Estas fases colocan el material con la geometría, espesor, densidad y acabado previstos en el proyecto.', E'Después de la descarga pueden ser necesarias operaciones de extendido, nivelación, compactación y refino. Estas fases colocan el material con la geometría, espesor, densidad y acabado previstos en el proyecto. En la aplicación práctica deben respetarse el manual del fabricante, las disposiciones internas de seguridad y el criterio de parada indicado.', array[E'Después de la descarga pueden ser necesarias operaciones de extendido, nivelación, compactación y refino', E'Estas fases colocan el material con la geometría, espesor, densidad y acabado previstos en el proyecto', E'Aplicar el manual del fabricante y las disposiciones internas']::text[], E'Detenga la operación y comunique cualquier condición que impida trabajar con seguridad.', E'ET 2001-1-08 · Presentación Cursos Pedro · Manual, páginas PDF 13 y 18–20', E'13 y 18–20', E'{courseVersionId}/block-1/audio/part-1-09.mp3', 16, 285923),
(1, 10, E'Definición de los trabajos y fases del movimiento de tierras', E'Sistemas mixtos: excavadora, pala y mototraílla', E'Los sistemas mixtos combinan varias funciones en una misma máquina. La excavadora puede arrancar y cargar, la pala puede cargar y realizar transporte corto y la mototraílla puede arrancar, cargar, transportar, descargar y extender en condiciones adecuadas.', E'Los sistemas mixtos combinan varias funciones en una misma máquina. La excavadora puede arrancar y cargar, la pala puede cargar y realizar transporte corto y la mototraílla puede arrancar, cargar, transportar, descargar y extender en condiciones adecuadas. En la aplicación práctica deben respetarse el manual del fabricante, las disposiciones internas de seguridad y el criterio de parada indicado.', array[E'Los sistemas mixtos combinan varias funciones en una misma máquina', E'La excavadora puede arrancar y cargar, la pala puede cargar y realizar transporte corto y la mototraílla puede…', E'Aplicar el manual del fabricante y las disposiciones internas']::text[], E'Detenga la operación y comunique cualquier condición que impida trabajar con seguridad.', E'ET 2001-1-08 · Presentación Cursos Pedro · Manual, páginas PDF 18–19', E'18–19', E'{courseVersionId}/block-1/audio/part-1-10.mp3', 21, 367425),
(2, 1, E'Normas preventivas antes de comenzar el trabajo', E'Preparación personal y equipos de protección', E'Antes de acceder a la máquina, compruebe que se encuentra en condiciones físicas y mentales adecuadas. Utilice ropa ajustada, calzado de seguridad, casco y los EPI definidos para el riesgo, sin olvidar que complementan, pero no sustituyen, las protecciones colectivas.', E'Antes de acceder a la máquina, compruebe que se encuentra en condiciones físicas y mentales adecuadas. Utilice ropa ajustada, calzado de seguridad, casco y los EPI definidos para el riesgo, sin olvidar que complementan, pero no sustituyen, las protecciones colectivas. En la aplicación práctica deben respetarse el manual del fabricante, las disposiciones internas de seguridad y el criterio de parada indicado.', array[E'Antes de acceder a la máquina, compruebe que se encuentra en condiciones físicas y mentales adecuadas', E'Utilice ropa ajustada, calzado de seguridad, casco y los EPI definidos para el riesgo, sin olvidar que…', E'Aplicar el manual del fabricante y las disposiciones internas']::text[], E'Detenga la operación y comunique cualquier condición que impida trabajar con seguridad.', E'ET 2001-1-08 · Presentación Cursos Pedro, diapositivas 13 y 44–46', E'consulta general', E'{courseVersionId}/block-2/audio/part-2-01.mp3', 27, 459817),
(2, 2, E'Normas preventivas antes de comenzar el trabajo', E'Inspección perimetral de la máquina', E'La revisión diaria comienza desde el suelo y con la máquina inmovilizada. Recorra todo el perímetro buscando personas, obstáculos, daños, fugas, piezas sueltas y acumulaciones de material. Registre cualquier anomalía y valórala antes del arranque.', E'La revisión diaria comienza desde el suelo y con la máquina inmovilizada. Recorra todo el perímetro buscando personas, obstáculos, daños, fugas, piezas sueltas y acumulaciones de material. Registre cualquier anomalía y valórala antes del arranque. En la aplicación práctica deben respetarse el manual del fabricante, las disposiciones internas de seguridad y el criterio de parada indicado.', array[E'La revisión diaria comienza desde el suelo y con la máquina inmovilizada', E'Recorra todo el perímetro buscando personas, obstáculos, daños, fugas, piezas sueltas y acumulaciones de…', E'Registre cualquier anomalía y valórala antes del arranque']::text[], E'Detenga la operación y comunique cualquier condición que impida trabajar con seguridad.', E'ET 2001-1-08 · Presentación Cursos Pedro, diapositivas 14 y 22', E'consulta general', E'{courseVersionId}/block-2/audio/part-2-02.mp3', 18, 310165),
(2, 3, E'Normas preventivas antes de comenzar el trabajo', E'Niveles, fugas y circuitos calientes', E'Compruebe los niveles con la máquina en la posición indicada por el fabricante. Nunca abra en caliente el circuito de refrigeración ni busque una fuga hidráulica con la mano. Si detecta combustible, una manguera dañada o una pérdida importante, inmovilice la máquina y comuníquelo.', E'Compruebe los niveles con la máquina en la posición indicada por el fabricante. Nunca abra en caliente el circuito de refrigeración ni busque una fuga hidráulica con la mano. Si detecta combustible, una manguera dañada o una pérdida importante, inmovilice la máquina y comuníquelo. En la aplicación práctica deben respetarse el manual del fabricante, las disposiciones internas de seguridad y el criterio de parada indicado.', array[E'Compruebe los niveles con la máquina en la posición indicada por el fabricante', E'Nunca abra en caliente el circuito de refrigeración ni busque una fuga hidráulica con la mano', E'Si detecta combustible, una manguera dañada o una pérdida importante, inmovilice la máquina y comuníquelo']::text[], E'Si detecta combustible, una manguera dañada o una pérdida importante, inmovilice la máquina y comuníquelo.', E'ET 2001-1-08 · 3.3.2.a · Presentación Cursos Pedro', E'consulta general', E'{courseVersionId}/block-2/audio/part-2-03.mp3', 17, 263358),
(2, 4, E'Normas preventivas antes de comenzar el trabajo', E'Neumáticos y tren de rodaje', E'En palas, revise presión, cortes, desgaste, llantas y fijaciones. En máquinas de cadenas, compruebe tejas, rodillos, rueda motriz y tensión aparente. No retire piedras ni intervenga en ruedas o cadenas sin detener, asegurar y aplicar el procedimiento previsto para esa operación.', E'En palas, revise presión, cortes, desgaste, llantas y fijaciones. En máquinas de cadenas, compruebe tejas, rodillos, rueda motriz y tensión aparente. No retire piedras ni intervenga en ruedas o cadenas sin detener, asegurar y aplicar el procedimiento previsto para esa operación. En la aplicación práctica deben respetarse el manual del fabricante, las disposiciones internas de seguridad y el criterio de parada indicado.', array[E'En palas, revise presión, cortes, desgaste, llantas y fijaciones', E'En máquinas de cadenas, compruebe tejas, rodillos, rueda motriz y tensión aparente', E'No retire piedras ni intervenga en ruedas o cadenas sin detener, asegurar y aplicar el procedimiento previsto…']::text[], E'Detenga la operación y comunique cualquier condición que impida trabajar con seguridad.', E'ET 2001-1-08 · 3.3.2.a · Presentación Cursos Pedro', E'consulta general', E'{courseVersionId}/block-2/audio/part-2-04.mp3', 19, 289271),
(2, 5, E'Normas preventivas antes de comenzar el trabajo', E'Equipo de trabajo y sistema hidráulico', E'Inspeccione cucharón, hoja, pluma, pasadores, dientes, cilindros y latiguillos. Una fisura o una fuga puede provocar pérdida de control o caída del accesorio. Nadie debe situarse bajo un equipo elevado sin bloqueo mecánico; para revisar, apoye el equipo y descargue la presión residual.', E'Inspeccione cucharón, hoja, pluma, pasadores, dientes, cilindros y latiguillos. Una fisura o una fuga puede provocar pérdida de control o caída del accesorio. Nadie debe situarse bajo un equipo elevado sin bloqueo mecánico; para revisar, apoye el equipo y descargue la presión residual. En la aplicación práctica deben respetarse el manual del fabricante, las disposiciones internas de seguridad y el criterio de parada indicado.', array[E'Inspeccione cucharón, hoja, pluma, pasadores, dientes, cilindros y latiguillos', E'Una fisura o una fuga puede provocar pérdida de control o caída del accesorio', E'Nadie debe situarse bajo un equipo elevado sin bloqueo mecánico; para revisar, apoye el equipo y descargue la…']::text[], E'Detenga la operación y comunique cualquier condición que impida trabajar con seguridad.', E'ET 2001-1-08 · 3.3.2.a · Presentación Cursos Pedro', E'consulta general', E'{courseVersionId}/block-2/audio/part-2-05.mp3', 19, 291779),
(2, 6, E'Normas preventivas antes de comenzar el trabajo', E'Acceso seguro y acondicionamiento de la cabina', E'Suba y baje mirando hacia la máquina y manteniendo tres puntos de apoyo. Limpie peldaños y asideros, ajuste asiento y espejos, retire objetos sueltos y compruebe la salida de emergencia. Abróchese el cinturón antes de mover el equipo y no salte nunca desde la cabina.', E'Suba y baje mirando hacia la máquina y manteniendo tres puntos de apoyo. Limpie peldaños y asideros, ajuste asiento y espejos, retire objetos sueltos y compruebe la salida de emergencia. Abróchese el cinturón antes de mover el equipo y no salte nunca desde la cabina. En la aplicación práctica deben respetarse el manual del fabricante, las disposiciones internas de seguridad y el criterio de parada indicado.', array[E'Suba y baje mirando hacia la máquina y manteniendo tres puntos de apoyo', E'Limpie peldaños y asideros, ajuste asiento y espejos, retire objetos sueltos y compruebe la salida de emergencia', E'Abróchese el cinturón antes de mover el equipo y no salte nunca desde la cabina']::text[], E'Abróchese el cinturón antes de mover el equipo y no salte nunca desde la cabina.', E'ET 2001-1-08 · 3.3.2.a · Presentación Cursos Pedro', E'consulta general', E'{courseVersionId}/block-2/audio/part-2-06.mp3', 17, 257506),
(2, 7, E'Normas preventivas antes de comenzar el trabajo', E'Comprobaciones funcionales antes de desplazarse', E'Después del arranque, observe el panel y pruebe frenos, dirección, bocina, alarma de retroceso, luces y mandos en una zona segura y a baja velocidad. Atienda a ruidos, vibraciones o respuestas lentas. Una alarma no se anula para continuar: se identifica la causa y se aplica el procedimiento.', E'Después del arranque, observe el panel y pruebe frenos, dirección, bocina, alarma de retroceso, luces y mandos en una zona segura y a baja velocidad. Atienda a ruidos, vibraciones o respuestas lentas. Una alarma no se anula para continuar: se identifica la causa y se aplica el procedimiento. En la aplicación práctica deben respetarse el manual del fabricante, las disposiciones internas de seguridad y el criterio de parada indicado.', array[E'Después del arranque, observe el panel y pruebe frenos, dirección, bocina, alarma de retroceso, luces y mandos…', E'Atienda a ruidos, vibraciones o respuestas lentas', E'Una alarma no se anula para continuar: se identifica la causa y se aplica el procedimiento']::text[], E'Detenga la operación y comunique cualquier condición que impida trabajar con seguridad.', E'ET 2001-1-08 · 3.3.2.a · Presentación Cursos Pedro', E'consulta general', E'{courseVersionId}/block-2/audio/part-2-07.mp3', 20, 312259),
(2, 8, E'Normas preventivas antes de comenzar el trabajo', E'Mantenimiento básico, bloqueo y consignación', E'Antes de una intervención, estacione en terreno firme, apoye el equipo, accione el freno, detenga el motor y controle la llave. Si existe energía eléctrica, hidráulica, neumática, mecánica o térmica, bloquee, consigne y verifique su ausencia. Nunca confíe solo en los cilindros hidráulicos.', E'Antes de una intervención, estacione en terreno firme, apoye el equipo, accione el freno, detenga el motor y controle la llave. Si existe energía eléctrica, hidráulica, neumática, mecánica o térmica, bloquee, consigne y verifique su ausencia. Nunca confíe solo en los cilindros hidráulicos. En la aplicación práctica deben respetarse el manual del fabricante, las disposiciones internas de seguridad y el criterio de parada indicado.', array[E'Antes de una intervención, estacione en terreno firme, apoye el equipo, accione el freno, detenga el motor y…', E'Si existe energía eléctrica, hidráulica, neumática, mecánica o térmica, bloquee, consigne y verifique su…', E'Nunca confíe solo en los cilindros hidráulicos']::text[], E'Nunca confíe solo en los cilindros hidráulicos.', E'ET 2001-1-08 · 3.3.2.a · Presentación Cursos Pedro', E'consulta general', E'{courseVersionId}/block-2/audio/part-2-08.mp3', 18, 280494),
(2, 9, E'Normas preventivas antes de comenzar el trabajo', E'Cambio seguro de accesorios', E'Cambie cucharas u otros accesorios sobre una superficie estable, sin personas alrededor y siguiendo la secuencia del fabricante. Libere la presión antes de desconectar circuitos. Tras el montaje, verifique pasadores, conexiones e indicadores de bloqueo y haga una prueba próxima al suelo.', E'Cambie cucharas u otros accesorios sobre una superficie estable, sin personas alrededor y siguiendo la secuencia del fabricante. Libere la presión antes de desconectar circuitos. Tras el montaje, verifique pasadores, conexiones e indicadores de bloqueo y haga una prueba próxima al suelo. En la aplicación práctica deben respetarse el manual del fabricante, las disposiciones internas de seguridad y el criterio de parada indicado.', array[E'Cambie cucharas u otros accesorios sobre una superficie estable, sin personas alrededor y siguiendo la…', E'Libere la presión antes de desconectar circuitos', E'Tras el montaje, verifique pasadores, conexiones e indicadores de bloqueo y haga una prueba próxima al suelo']::text[], E'Detenga la operación y comunique cualquier condición que impida trabajar con seguridad.', E'ET 2001-1-08 · 3.3.2.a · Presentación Cursos Pedro', E'consulta general', E'{courseVersionId}/block-2/audio/part-2-09.mp3', 17, 261268),
(2, 10, E'Normas preventivas antes de comenzar el trabajo', E'Embarque, transporte, remolcado y recuperación', E'El embarque y el remolcado requieren un plan, medios certificados y puntos de amarre o anclaje previstos por el fabricante. Mantenga despejada la zona de posible latigazo de cables y eslingas. Si la máquina está hundida, en pendiente o junto a un borde, estabilice primero la situación.', E'El embarque y el remolcado requieren un plan, medios certificados y puntos de amarre o anclaje previstos por el fabricante. Mantenga despejada la zona de posible latigazo de cables y eslingas. Si la máquina está hundida, en pendiente o junto a un borde, estabilice primero la situación. En la aplicación práctica deben respetarse el manual del fabricante, las disposiciones internas de seguridad y el criterio de parada indicado.', array[E'El embarque y el remolcado requieren un plan, medios certificados y puntos de amarre o anclaje previstos por…', E'Mantenga despejada la zona de posible latigazo de cables y eslingas', E'Si la máquina está hundida, en pendiente o junto a un borde, estabilice primero la situación']::text[], E'Si la máquina está hundida, en pendiente o junto a un borde, estabilice primero la situación.', E'ET 2001-1-08 · 3.3.2.a · Presentación Cursos Pedro', E'consulta general', E'{courseVersionId}/block-2/audio/part-2-10.mp3', 16, 255835),
(3, 1, E'Normas preventivas durante el trabajo', E'Arranque, calentamiento y preparación operativa', E'Arranque siempre desde el puesto del operador, con los mandos neutralizados y el entorno despejado. Durante el calentamiento vigile presión de aceite, temperatura y mensajes del panel. Si aparecen humo anormal, golpes o una alarma persistente, detenga la máquina e informe antes de trabajar.', E'Arranque siempre desde el puesto del operador, con los mandos neutralizados y el entorno despejado. Durante el calentamiento vigile presión de aceite, temperatura y mensajes del panel. Si aparecen humo anormal, golpes o una alarma persistente, detenga la máquina e informe antes de trabajar. En la aplicación práctica deben respetarse el manual del fabricante, las disposiciones internas de seguridad y el criterio de parada indicado.', array[E'Arranque siempre desde el puesto del operador, con los mandos neutralizados y el entorno despejado', E'Durante el calentamiento vigile presión de aceite, temperatura y mensajes del panel', E'Si aparecen humo anormal, golpes o una alarma persistente, detenga la máquina e informe antes de trabajar']::text[], E'Si aparecen humo anormal, golpes o una alarma persistente, detenga la máquina e informe antes de trabajar.', E'ET 2001-1-08 · 3.3.2.b · Presentación Cursos Pedro', E'consulta general', E'{courseVersionId}/block-3/audio/part-3-01.mp3', 17, 272971),
(3, 2, E'Normas preventivas durante el trabajo', E'Visibilidad, zonas ciegas y control del área', E'Cámaras, espejos y alarmas ayudan, pero no eliminan las zonas ciegas. Antes de moverse, observe, avise y espere. Si la maniobra necesita un señalista, manténgalo siempre visible y utilice señales acordadas. Si pierde el contacto, detenga inmediatamente la máquina.', E'Cámaras, espejos y alarmas ayudan, pero no eliminan las zonas ciegas. Antes de moverse, observe, avise y espere. Si la maniobra necesita un señalista, manténgalo siempre visible y utilice señales acordadas. Si pierde el contacto, detenga inmediatamente la máquina. En la aplicación práctica deben respetarse el manual del fabricante, las disposiciones internas de seguridad y el criterio de parada indicado.', array[E'Cámaras, espejos y alarmas ayudan, pero no eliminan las zonas ciegas', E'Antes de moverse, observe, avise y espere', E'Si la maniobra necesita un señalista, manténgalo siempre visible y utilice señales acordadas']::text[], E'Si pierde el contacto, detenga inmediatamente la máquina.', E'ET 2001-1-08 · 3.3.2.b · Presentación Cursos Pedro', E'consulta general', E'{courseVersionId}/block-3/audio/part-3-02.mp3', 19, 290107),
(3, 3, E'Normas preventivas durante el trabajo', E'Carga segura con pala cargadora', E'Aproxímese al acopio con el cucharón bajo y los bastidores alineados. Llene sin embestir, retroceda mirando la trayectoria y transporte la carga baja y estable. Al descargar sobre un camión, no golpee la caja ni pase sobre la cabina, y distribuya el material de forma uniforme.', E'Aproxímese al acopio con el cucharón bajo y los bastidores alineados. Llene sin embestir, retroceda mirando la trayectoria y transporte la carga baja y estable. Al descargar sobre un camión, no golpee la caja ni pase sobre la cabina, y distribuya el material de forma uniforme. En la aplicación práctica deben respetarse el manual del fabricante, las disposiciones internas de seguridad y el criterio de parada indicado.', array[E'Aproxímese al acopio con el cucharón bajo y los bastidores alineados', E'Llene sin embestir, retroceda mirando la trayectoria y transporte la carga baja y estable', E'Al descargar sobre un camión, no golpee la caja ni pase sobre la cabina, y distribuya el material de forma…']::text[], E'Al descargar sobre un camión, no golpee la caja ni pase sobre la cabina, y distribuya el material de forma uniforme.', E'ET 2001-1-08 · 3.3.2.b · Presentación Cursos Pedro', E'consulta general', E'{courseVersionId}/block-3/audio/part-3-03.mp3', 18, 277568),
(3, 4, E'Normas preventivas durante el trabajo', E'Excavación y carga con excavadora hidráulica', E'Trabaje desde una plataforma resistente y con el radio de giro despejado. Identifique servicios enterrados y evalúe el frente o la zanja. Coloque el camión fuera de la caída de material y evite pasar la cuchara sobre su cabina. Si pierde visibilidad o comunicación, detenga el ciclo.', E'Trabaje desde una plataforma resistente y con el radio de giro despejado. Identifique servicios enterrados y evalúe el frente o la zanja. Coloque el camión fuera de la caída de material y evite pasar la cuchara sobre su cabina. Si pierde visibilidad o comunicación, detenga el ciclo. En la aplicación práctica deben respetarse el manual del fabricante, las disposiciones internas de seguridad y el criterio de parada indicado.', array[E'Trabaje desde una plataforma resistente y con el radio de giro despejado', E'Identifique servicios enterrados y evalúe el frente o la zanja', E'Coloque el camión fuera de la caída de material y evite pasar la cuchara sobre su cabina']::text[], E'Si pierde visibilidad o comunicación, detenga el ciclo.', E'ET 2001-1-08 · 3.3.2.b · Presentación Cursos Pedro', E'consulta general', E'{courseVersionId}/block-3/audio/part-3-04.mp3', 17, 266284),
(3, 5, E'Normas preventivas durante el trabajo', E'Operación segura con tractor de cadenas', E'En pendientes, trabaje según la dirección definida por el fabricante y evite giros bruscos o desplazamientos laterales. Lleve la hoja baja y mantenga distancia a bordes y coronaciones. Si aparecen vibraciones, pérdida de control o una resistencia imprevista, detenga la operación.', E'En pendientes, trabaje según la dirección definida por el fabricante y evite giros bruscos o desplazamientos laterales. Lleve la hoja baja y mantenga distancia a bordes y coronaciones. Si aparecen vibraciones, pérdida de control o una resistencia imprevista, detenga la operación. En la aplicación práctica deben respetarse el manual del fabricante, las disposiciones internas de seguridad y el criterio de parada indicado.', array[E'En pendientes, trabaje según la dirección definida por el fabricante y evite giros bruscos o desplazamientos…', E'Lleve la hoja baja y mantenga distancia a bordes y coronaciones', E'Si aparecen vibraciones, pérdida de control o una resistencia imprevista, detenga la operación']::text[], E'Si aparecen vibraciones, pérdida de control o una resistencia imprevista, detenga la operación.', E'ET 2001-1-08 · 3.3.2.b · Presentación Cursos Pedro', E'consulta general', E'{courseVersionId}/block-3/audio/part-3-05.mp3', 16, 253745),
(3, 6, E'Normas preventivas durante el trabajo', E'Circulación por pistas, rampas y cruces', E'Adapte la velocidad a la carga, visibilidad, pendiente, firme y tráfico. Respete sentidos, prioridades y distancias de seguridad de las disposiciones internas. En rampas no circule en punto muerto y use la relación recomendada. Polvo, lluvia, barro o baches obligan a reducir la marcha.', E'Adapte la velocidad a la carga, visibilidad, pendiente, firme y tráfico. Respete sentidos, prioridades y distancias de seguridad de las disposiciones internas. En rampas no circule en punto muerto y use la relación recomendada. Polvo, lluvia, barro o baches obligan a reducir la marcha. En la aplicación práctica deben respetarse el manual del fabricante, las disposiciones internas de seguridad y el criterio de parada indicado.', array[E'Adapte la velocidad a la carga, visibilidad, pendiente, firme y tráfico', E'Respete sentidos, prioridades y distancias de seguridad de las disposiciones internas', E'En rampas no circule en punto muerto y use la relación recomendada']::text[], E'En rampas no circule en punto muerto y use la relación recomendada.', E'ET 2001-1-08 · 3.3.2.b · Presentación Cursos Pedro', E'consulta general', E'{courseVersionId}/block-3/audio/part-3-06.mp3', 22, 343606),
(3, 7, E'Normas preventivas durante el trabajo', E'Taludes, frentes, zanjas y bordes', E'Respete las distancias de seguridad definidas según la altura, el material, la humedad y las sobrecargas. No trabaje bajo bloques o viseras sin sanear ni socave la plataforma de la máquina. Si aparecen grietas, caída de fragmentos o deformaciones, retírese e informe.', E'Respete las distancias de seguridad definidas según la altura, el material, la humedad y las sobrecargas. No trabaje bajo bloques o viseras sin sanear ni socave la plataforma de la máquina. Si aparecen grietas, caída de fragmentos o deformaciones, retírese e informe. En la aplicación práctica deben respetarse el manual del fabricante, las disposiciones internas de seguridad y el criterio de parada indicado.', array[E'Respete las distancias de seguridad definidas según la altura, el material, la humedad y las sobrecargas', E'No trabaje bajo bloques o viseras sin sanear ni socave la plataforma de la máquina', E'Si aparecen grietas, caída de fragmentos o deformaciones, retírese e informe']::text[], E'Si aparecen grietas, caída de fragmentos o deformaciones, retírese e informe.', E'ET 2001-1-08 · 3.3.2.b · Presentación Cursos Pedro', E'consulta general', E'{courseVersionId}/block-3/audio/part-3-07.mp3', 17, 258342),
(3, 8, E'Normas preventivas durante el trabajo', E'Descarga en camiones, tolvas y acopios', E'Controle la trayectoria y distribución del material durante la descarga. No sobrecargue camiones ni confíe en topes o bermas como freno. Mantenga a las personas fuera del punto de vertido. Si el material queda adherido, no dé golpes violentos: pare, aísle y aplique el procedimiento de desatasco.', E'Controle la trayectoria y distribución del material durante la descarga. No sobrecargue camiones ni confíe en topes o bermas como freno. Mantenga a las personas fuera del punto de vertido. Si el material queda adherido, no dé golpes violentos: pare, aísle y aplique el procedimiento de desatasco. En la aplicación práctica deben respetarse el manual del fabricante, las disposiciones internas de seguridad y el criterio de parada indicado.', array[E'Controle la trayectoria y distribución del material durante la descarga', E'No sobrecargue camiones ni confíe en topes o bermas como freno', E'Mantenga a las personas fuera del punto de vertido']::text[], E'Si el material queda adherido, no dé golpes violentos: pare, aísle y aplique el procedimiento de desatasco.', E'ET 2001-1-08 · 3.3.2.b · Presentación Cursos Pedro', E'consulta general', E'{courseVersionId}/block-3/audio/part-3-08.mp3', 17, 261268),
(3, 9, E'Normas preventivas durante el trabajo', E'Elevación de cargas con maquinaria', E'Una pala o excavadora solo puede elevar cargas si el fabricante lo permite y existe un procedimiento autorizado. Conozca el peso, el radio y la capacidad de la configuración real. Use puntos y accesorios certificados, desplace la carga baja y nunca permita el paso de personas debajo.', E'Una pala o excavadora solo puede elevar cargas si el fabricante lo permite y existe un procedimiento autorizado. Conozca el peso, el radio y la capacidad de la configuración real. Use puntos y accesorios certificados, desplace la carga baja y nunca permita el paso de personas debajo. En la aplicación práctica deben respetarse el manual del fabricante, las disposiciones internas de seguridad y el criterio de parada indicado.', array[E'Una pala o excavadora solo puede elevar cargas si el fabricante lo permite y existe un procedimiento autorizado', E'Conozca el peso, el radio y la capacidad de la configuración real', E'Use puntos y accesorios certificados, desplace la carga baja y nunca permita el paso de personas debajo']::text[], E'Use puntos y accesorios certificados, desplace la carga baja y nunca permita el paso de personas debajo.', E'ET 2001-1-08 · 3.3.2.b · Presentación Cursos Pedro', E'consulta general', E'{courseVersionId}/block-3/audio/part-3-09.mp3', 16, 256671),
(3, 10, E'Normas preventivas durante el trabajo', E'Estacionamiento, parada y comunicación de incidencias', E'Estacione en la zona designada, sobre terreno firme, con transmisión en neutro, freno aplicado y equipo completamente apoyado. Siga el enfriamiento indicado, retire la llave y cierre la cabina. Registre y comunique fugas, alarmas o golpes; si afectan a la seguridad, deje la máquina fuera de servicio.', E'Estacione en la zona designada, sobre terreno firme, con transmisión en neutro, freno aplicado y equipo completamente apoyado. Siga el enfriamiento indicado, retire la llave y cierre la cabina. Registre y comunique fugas, alarmas o golpes; si afectan a la seguridad, deje la máquina fuera de servicio. En la aplicación práctica deben respetarse el manual del fabricante, las disposiciones internas de seguridad y el criterio de parada indicado.', array[E'Estacione en la zona designada, sobre terreno firme, con transmisión en neutro, freno aplicado y equipo…', E'Siga el enfriamiento indicado, retire la llave y cierre la cabina', E'Registre y comunique fugas, alarmas o golpes; si afectan a la seguridad, deje la máquina fuera de servicio']::text[], E'Registre y comunique fugas, alarmas o golpes; si afectan a la seguridad, deje la máquina fuera de servicio.', E'ET 2001-1-08 · 3.3.2.b · Presentación Cursos Pedro', E'consulta general', E'{courseVersionId}/block-3/audio/part-3-10.mp3', 20, 317693),
(4, 1, E'Componentes de la máquina y sistemas de seguridad', E'Motor, refrigeración y lubricación', E'Vigile presión de aceite, temperatura del refrigerante, combustible e indicadores. Un sobrecalentamiento puede deberse a falta de nivel, radiadores obstruidos o una avería del ventilador. Detenga y diagnostique según el manual; nunca abra el circuito en caliente ni tape una alarma.', E'Vigile presión de aceite, temperatura del refrigerante, combustible e indicadores. Un sobrecalentamiento puede deberse a falta de nivel, radiadores obstruidos o una avería del ventilador. Detenga y diagnostique según el manual; nunca abra el circuito en caliente ni tape una alarma. En la aplicación práctica deben respetarse el manual del fabricante, las disposiciones internas de seguridad y el criterio de parada indicado.', array[E'Vigile presión de aceite, temperatura del refrigerante, combustible e indicadores', E'Un sobrecalentamiento puede deberse a falta de nivel, radiadores obstruidos o una avería del ventilador', E'Detenga y diagnostique según el manual; nunca abra el circuito en caliente ni tape una alarma']::text[], E'Detenga y diagnostique según el manual; nunca abra el circuito en caliente ni tape una alarma.', E'ET 2001-1-08 · 3.3.3 · Presentación Cursos Pedro', E'consulta general', E'{courseVersionId}/block-4/audio/part-4-01.mp3', 16, 252909),
(4, 2, E'Componentes de la máquina y sistemas de seguridad', E'Transmisión, articulación y tracción', E'La transmisión lleva la potencia a ruedas o cadenas. En una pala, la articulación central crea una zona de aplastamiento que debe bloquearse antes de trabajar entre bastidores. Evite cambios bruscos, patinamientos y esfuerzos excesivos. Cualquier tirón, ruido o pérdida de tracción debe comunicarse.', E'La transmisión lleva la potencia a ruedas o cadenas. En una pala, la articulación central crea una zona de aplastamiento que debe bloquearse antes de trabajar entre bastidores. Evite cambios bruscos, patinamientos y esfuerzos excesivos. Cualquier tirón, ruido o pérdida de tracción debe comunicarse. En la aplicación práctica deben respetarse el manual del fabricante, las disposiciones internas de seguridad y el criterio de parada indicado.', array[E'La transmisión lleva la potencia a ruedas o cadenas', E'En una pala, la articulación central crea una zona de aplastamiento que debe bloquearse antes de trabajar…', E'Evite cambios bruscos, patinamientos y esfuerzos excesivos']::text[], E'Detenga la operación y comunique cualquier condición que impida trabajar con seguridad.', E'ET 2001-1-08 · 3.3.3 · Presentación Cursos Pedro', E'consulta general', E'{courseVersionId}/block-4/audio/part-4-02.mp3', 18, 285510),
(4, 3, E'Componentes de la máquina y sistemas de seguridad', E'Sistema hidráulico y energía acumulada', E'El sistema hidráulico puede conservar presión incluso con el motor parado. Antes de intervenir, apoye el equipo, descargue la presión y bloquee los movimientos posibles. No busque fugas con la mano. Si aparecen movimientos espontáneos o el equipo baja sin orden, retire la máquina de servicio.', E'El sistema hidráulico puede conservar presión incluso con el motor parado. Antes de intervenir, apoye el equipo, descargue la presión y bloquee los movimientos posibles. No busque fugas con la mano. Si aparecen movimientos espontáneos o el equipo baja sin orden, retire la máquina de servicio. En la aplicación práctica deben respetarse el manual del fabricante, las disposiciones internas de seguridad y el criterio de parada indicado.', array[E'El sistema hidráulico puede conservar presión incluso con el motor parado', E'Antes de intervenir, apoye el equipo, descargue la presión y bloquee los movimientos posibles', E'No busque fugas con la mano']::text[], E'Si aparecen movimientos espontáneos o el equipo baja sin orden, retire la máquina de servicio.', E'ET 2001-1-08 · 3.3.3 · Presentación Cursos Pedro', E'consulta general', E'{courseVersionId}/block-4/audio/part-4-03.mp3', 18, 281330),
(4, 4, E'Componentes de la máquina y sistemas de seguridad', E'Equipos de trabajo, accesorios y capacidades', E'Cada accesorio cambia el peso, el centro de gravedad y la capacidad de la máquina. Compruebe compatibilidad, presión, caudal, retención y tabla de carga para la configuración real. No use cucharas, horquillas o martillos para funciones no previstas ni improvise puntos de izado.', E'Cada accesorio cambia el peso, el centro de gravedad y la capacidad de la máquina. Compruebe compatibilidad, presión, caudal, retención y tabla de carga para la configuración real. No use cucharas, horquillas o martillos para funciones no previstas ni improvise puntos de izado. En la aplicación práctica deben respetarse el manual del fabricante, las disposiciones internas de seguridad y el criterio de parada indicado.', array[E'Cada accesorio cambia el peso, el centro de gravedad y la capacidad de la máquina', E'Compruebe compatibilidad, presión, caudal, retención y tabla de carga para la configuración real', E'No use cucharas, horquillas o martillos para funciones no previstas ni improvise puntos de izado']::text[], E'Detenga la operación y comunique cualquier condición que impida trabajar con seguridad.', E'ET 2001-1-08 · 3.3.3 · Presentación Cursos Pedro', E'consulta general', E'{courseVersionId}/block-4/audio/part-4-04.mp3', 18, 287182),
(4, 5, E'Componentes de la máquina y sistemas de seguridad', E'Neumáticos, cadenas y contacto con el terreno', E'Neumáticos y cadenas condicionan dirección, frenado y estabilidad. Revise presión, cortes, desgaste, barro acumulado y tensión del tren de rodaje. Una máquina pesada puede hundirse aunque la superficie parezca firme; confirme la capacidad portante antes de trabajar sobre rellenos, bordes o plataformas recientes.', E'Neumáticos y cadenas condicionan dirección, frenado y estabilidad. Revise presión, cortes, desgaste, barro acumulado y tensión del tren de rodaje. Una máquina pesada puede hundirse aunque la superficie parezca firme; confirme la capacidad portante antes de trabajar sobre rellenos, bordes o plataformas recientes. En la aplicación práctica deben respetarse el manual del fabricante, las disposiciones internas de seguridad y el criterio de parada indicado.', array[E'Neumáticos y cadenas condicionan dirección, frenado y estabilidad', E'Revise presión, cortes, desgaste, barro acumulado y tensión del tren de rodaje', E'Una máquina pesada puede hundirse aunque la superficie parezca firme; confirme la capacidad portante antes de…']::text[], E'Detenga la operación y comunique cualquier condición que impida trabajar con seguridad.', E'ET 2001-1-08 · 3.3.3 · Presentación Cursos Pedro', E'consulta general', E'{courseVersionId}/block-4/audio/part-4-05.mp3', 22, 347368),
(4, 6, E'Componentes de la máquina y sistemas de seguridad', E'Frenos, dirección y control del movimiento', E'Pruebe freno de servicio, estacionamiento y sistemas de emergencia conforme al manual. La dirección de emergencia permite conservar el control, pero no continuar la producción tras una avería. Si cambia la respuesta, aumenta el recorrido o aparece una alarma, estacione de forma segura y solicite revisión.', E'Pruebe freno de servicio, estacionamiento y sistemas de emergencia conforme al manual. La dirección de emergencia permite conservar el control, pero no continuar la producción tras una avería. Si cambia la respuesta, aumenta el recorrido o aparece una alarma, estacione de forma segura y solicite revisión. En la aplicación práctica deben respetarse el manual del fabricante, las disposiciones internas de seguridad y el criterio de parada indicado.', array[E'Pruebe freno de servicio, estacionamiento y sistemas de emergencia conforme al manual', E'La dirección de emergencia permite conservar el control, pero no continuar la producción tras una avería', E'Si cambia la respuesta, aumenta el recorrido o aparece una alarma, estacione de forma segura y solicite revisión']::text[], E'Si cambia la respuesta, aumenta el recorrido o aparece una alarma, estacione de forma segura y solicite revisión.', E'ET 2001-1-08 · 3.3.3 · Presentación Cursos Pedro', E'consulta general', E'{courseVersionId}/block-4/audio/part-4-06.mp3', 17, 270881),
(4, 7, E'Componentes de la máquina y sistemas de seguridad', E'ROPS, FOPS y cinturón de seguridad', E'Las estructuras ROPS protegen en caso de vuelco y las FOPS frente a la caída de objetos, dentro de sus condiciones de diseño. No deben perforarse, soldarse ni modificarse sin autorización. El cinturón mantiene al operador dentro del espacio protegido y debe utilizarse siempre durante el trabajo.', E'Las estructuras ROPS protegen en caso de vuelco y las FOPS frente a la caída de objetos, dentro de sus condiciones de diseño. No deben perforarse, soldarse ni modificarse sin autorización. El cinturón mantiene al operador dentro del espacio protegido y debe utilizarse siempre durante el trabajo. En la aplicación práctica deben respetarse el manual del fabricante, las disposiciones internas de seguridad y el criterio de parada indicado.', array[E'Las estructuras ROPS protegen en caso de vuelco y las FOPS frente a la caída de objetos, dentro de sus…', E'No deben perforarse, soldarse ni modificarse sin autorización', E'El cinturón mantiene al operador dentro del espacio protegido y debe utilizarse siempre durante el trabajo']::text[], E'No deben perforarse, soldarse ni modificarse sin autorización.', E'ET 2001-1-08 · 3.3.3 · Presentación Cursos Pedro', E'consulta general', E'{courseVersionId}/block-4/audio/part-4-07.mp3', 19, 295959),
(4, 8, E'Componentes de la máquina y sistemas de seguridad', E'Bloqueos, resguardos y prevención del movimiento', E'Los bloqueos mecánicos evitan movimientos por gravedad, pérdida de presión o accionamiento involuntario. Los resguardos separan de correas, ventiladores y elementos giratorios. No anule ninguna protección. Antes de retirar un bloqueo, compruebe que no quedan personas, herramientas ni soportes en la zona.', E'Los bloqueos mecánicos evitan movimientos por gravedad, pérdida de presión o accionamiento involuntario. Los resguardos separan de correas, ventiladores y elementos giratorios. No anule ninguna protección. Antes de retirar un bloqueo, compruebe que no quedan personas, herramientas ni soportes en la zona. En la aplicación práctica deben respetarse el manual del fabricante, las disposiciones internas de seguridad y el criterio de parada indicado.', array[E'Los bloqueos mecánicos evitan movimientos por gravedad, pérdida de presión o accionamiento involuntario', E'Los resguardos separan de correas, ventiladores y elementos giratorios', E'No anule ninguna protección']::text[], E'No anule ninguna protección.', E'ET 2001-1-08 · 3.3.3 · Presentación Cursos Pedro', E'consulta general', E'{courseVersionId}/block-4/audio/part-4-08.mp3', 19, 290107),
(4, 9, E'Componentes de la máquina y sistemas de seguridad', E'Instrumentos, alarmas y dispositivos de aviso', E'Manómetros, termómetros y alarmas informan del estado de los sistemas. Conozca la lectura normal y la respuesta exigida para cada aviso. Bocina, cámara, luces y alarma de retroceso ayudan, pero no sustituyen una zona despejada. No tape indicadores ni desconecte alarmas.', E'Manómetros, termómetros y alarmas informan del estado de los sistemas. Conozca la lectura normal y la respuesta exigida para cada aviso. Bocina, cámara, luces y alarma de retroceso ayudan, pero no sustituyen una zona despejada. No tape indicadores ni desconecte alarmas. En la aplicación práctica deben respetarse el manual del fabricante, las disposiciones internas de seguridad y el criterio de parada indicado.', array[E'Manómetros, termómetros y alarmas informan del estado de los sistemas', E'Conozca la lectura normal y la respuesta exigida para cada aviso', E'Bocina, cámara, luces y alarma de retroceso ayudan, pero no sustituyen una zona despejada']::text[], E'No tape indicadores ni desconecte alarmas.', E'ET 2001-1-08 · 3.3.3 · Presentación Cursos Pedro', E'consulta general', E'{courseVersionId}/block-4/audio/part-4-09.mp3', 19, 292197),
(4, 10, E'Componentes de la máquina y sistemas de seguridad', E'Manual del fabricante y adecuación al Real Decreto 1215/1997', E'El manual define el uso previsto, las capacidades y el mantenimiento de cada modelo. La máquina debe cumplir las disposiciones aplicables del Real Decreto 1215 de 1997 y mantener sus protecciones en buen estado. Si se modifica la configuración o se añade un accesorio, deben evaluarse de nuevo los riesgos.', E'El manual define el uso previsto, las capacidades y el mantenimiento de cada modelo. La máquina debe cumplir las disposiciones aplicables del Real Decreto 1215 de 1997 y mantener sus protecciones en buen estado. Si se modifica la configuración o se añade un accesorio, deben evaluarse de nuevo los riesgos. En la aplicación práctica deben respetarse el manual del fabricante, las disposiciones internas de seguridad y el criterio de parada indicado.', array[E'El manual define el uso previsto, las capacidades y el mantenimiento de cada modelo', E'La máquina debe cumplir las disposiciones aplicables del Real Decreto 1215 de 1997 y mantener sus protecciones…', E'Si se modifica la configuración o se añade un accesorio, deben evaluarse de nuevo los riesgos']::text[], E'Si se modifica la configuración o se añade un accesorio, deben evaluarse de nuevo los riesgos.', E'ET 2001-1-08 · 3.3.3 · Presentación Cursos Pedro', E'consulta general', E'{courseVersionId}/block-4/audio/part-4-10.mp3', 21, 325634),
(5, 1, E'Control del entorno, interferencias, emergencias y normativa', E'Vigilancia de frentes, plataformas y taludes', E'Observe el frente, la plataforma y los taludes antes y durante el trabajo. Grietas, agua, bloques sueltos o material recién volado pueden cambiar la estabilidad. Repita la inspección después de lluvias, heladas o voladuras. Ante cualquier duda, retire la máquina fuera del alcance y solicite evaluación.', E'Observe el frente, la plataforma y los taludes antes y durante el trabajo. Grietas, agua, bloques sueltos o material recién volado pueden cambiar la estabilidad. Repita la inspección después de lluvias, heladas o voladuras. Ante cualquier duda, retire la máquina fuera del alcance y solicite evaluación. En la aplicación práctica deben respetarse el manual del fabricante, las disposiciones internas de seguridad y el criterio de parada indicado.', array[E'Observe el frente, la plataforma y los taludes antes y durante el trabajo', E'Grietas, agua, bloques sueltos o material recién volado pueden cambiar la estabilidad', E'Repita la inspección después de lluvias, heladas o voladuras']::text[], E'Detenga la operación y comunique cualquier condición que impida trabajar con seguridad.', E'ET 2001-1-08 · 3.3.4 · Presentación Cursos Pedro', E'consulta general', E'{courseVersionId}/block-5/audio/part-5-01.mp3', 20, 308079),
(5, 2, E'Control del entorno, interferencias, emergencias y normativa', E'Pistas, bermas, drenaje y control del polvo', E'Las pistas deben tener anchura, firme, visibilidad y drenaje adecuados. Baches, barro y polvo reducen el control. Las bermas delimitan el borde, pero no son un freno ni garantizan su resistencia. Adapte la velocidad e informe de los deterioros; si la circulación no es segura, detenga su uso.', E'Las pistas deben tener anchura, firme, visibilidad y drenaje adecuados. Baches, barro y polvo reducen el control. Las bermas delimitan el borde, pero no son un freno ni garantizan su resistencia. Adapte la velocidad e informe de los deterioros; si la circulación no es segura, detenga su uso. En la aplicación práctica deben respetarse el manual del fabricante, las disposiciones internas de seguridad y el criterio de parada indicado.', array[E'Las pistas deben tener anchura, firme, visibilidad y drenaje adecuados', E'Baches, barro y polvo reducen el control', E'Las bermas delimitan el borde, pero no son un freno ni garantizan su resistencia']::text[], E'Adapte la velocidad e informe de los deterioros; si la circulación no es segura, detenga su uso.', E'ET 2001-1-08 · 3.3.4 · Presentación Cursos Pedro', E'consulta general', E'{courseVersionId}/block-5/audio/part-5-02.mp3', 19, 301810),
(5, 3, E'Control del entorno, interferencias, emergencias y normativa', E'Interferencia entre pala cargadora y camión', E'El punto de espera, la entrada y la salida del camión deben estar definidos. La pala no inicia el ciclo hasta confirmar su posición, evita pasar el cucharón sobre la cabina y distribuye la carga sin golpes. Si aparece una persona o se pierde la comunicación, ambos equipos se detienen.', E'El punto de espera, la entrada y la salida del camión deben estar definidos. La pala no inicia el ciclo hasta confirmar su posición, evita pasar el cucharón sobre la cabina y distribuye la carga sin golpes. Si aparece una persona o se pierde la comunicación, ambos equipos se detienen. En la aplicación práctica deben respetarse el manual del fabricante, las disposiciones internas de seguridad y el criterio de parada indicado.', array[E'El punto de espera, la entrada y la salida del camión deben estar definidos', E'La pala no inicia el ciclo hasta confirmar su posición, evita pasar el cucharón sobre la cabina y distribuye…', E'Si aparece una persona o se pierde la comunicación, ambos equipos se detienen']::text[], E'Si aparece una persona o se pierde la comunicación, ambos equipos se detienen.', E'ET 2001-1-08 · 3.3.5 · Presentación Cursos Pedro', E'consulta general', E'{courseVersionId}/block-5/audio/part-5-03.mp3', 17, 267119),
(5, 4, E'Control del entorno, interferencias, emergencias y normativa', E'Interferencia entre excavadora y vehículo de transporte', E'Coloque el vehículo fuera del radio de giro y de la posible caída de material. Reduzca el giro y evite pasar la cuchara sobre la cabina. El conductor no moverá el camión hasta recibir la señal. Una sola persona dirige la maniobra y cualquier pérdida de comunicación exige parada inmediata.', E'Coloque el vehículo fuera del radio de giro y de la posible caída de material. Reduzca el giro y evite pasar la cuchara sobre la cabina. El conductor no moverá el camión hasta recibir la señal. Una sola persona dirige la maniobra y cualquier pérdida de comunicación exige parada inmediata. En la aplicación práctica deben respetarse el manual del fabricante, las disposiciones internas de seguridad y el criterio de parada indicado.', array[E'Coloque el vehículo fuera del radio de giro y de la posible caída de material', E'Reduzca el giro y evite pasar la cuchara sobre la cabina', E'El conductor no moverá el camión hasta recibir la señal']::text[], E'Detenga la operación y comunique cualquier condición que impida trabajar con seguridad.', E'ET 2001-1-08 · 3.3.5 · Presentación Cursos Pedro', E'consulta general', E'{courseVersionId}/block-5/audio/part-5-04.mp3', 18, 277568),
(5, 5, E'Control del entorno, interferencias, emergencias y normativa', E'Personal de tierra, señalistas y comunicaciones', E'Las rutas peatonales y zonas de exclusión deben estar definidas. Para acercarse a una máquina, establezca contacto y espere la confirmación del operador. El señalista debe permanecer visible y usar señales acordadas. Si varias personas dan instrucciones o una orden es ambigua, detenga el trabajo y aclare la maniobra.', E'Las rutas peatonales y zonas de exclusión deben estar definidas. Para acercarse a una máquina, establezca contacto y espere la confirmación del operador. El señalista debe permanecer visible y usar señales acordadas. Si varias personas dan instrucciones o una orden es ambigua, detenga el trabajo y aclare la maniobra. En la aplicación práctica deben respetarse el manual del fabricante, las disposiciones internas de seguridad y el criterio de parada indicado.', array[E'Las rutas peatonales y zonas de exclusión deben estar definidas', E'Para acercarse a una máquina, establezca contacto y espere la confirmación del operador', E'El señalista debe permanecer visible y usar señales acordadas']::text[], E'Si varias personas dan instrucciones o una orden es ambigua, detenga el trabajo y aclare la maniobra.', E'ET 2001-1-08 · 3.3.5 · Presentación Cursos Pedro', E'consulta general', E'{courseVersionId}/block-5/audio/part-5-05.mp3', 19, 290943),
(5, 6, E'Control del entorno, interferencias, emergencias y normativa', E'Trabajos próximos a líneas eléctricas', E'Una línea aérea puede producir arco sin contacto. Identifique tensión, altura y recorrido, y aplique las distancias y medidas del procedimiento específico. Considere todas las posiciones de pluma y carga. Si hay contacto, permanezca en la cabina salvo peligro inmediato y active el plan de emergencia.', E'Una línea aérea puede producir arco sin contacto. Identifique tensión, altura y recorrido, y aplique las distancias y medidas del procedimiento específico. Considere todas las posiciones de pluma y carga. Si hay contacto, permanezca en la cabina salvo peligro inmediato y active el plan de emergencia. En la aplicación práctica deben respetarse el manual del fabricante, las disposiciones internas de seguridad y el criterio de parada indicado.', array[E'Una línea aérea puede producir arco sin contacto', E'Identifique tensión, altura y recorrido, y aplique las distancias y medidas del procedimiento específico', E'Considere todas las posiciones de pluma y carga']::text[], E'Si hay contacto, permanezca en la cabina salvo peligro inmediato y active el plan de emergencia.', E'ET 2001-1-08 · 3.3.5 · Presentación Cursos Pedro', E'consulta general', E'{courseVersionId}/block-5/audio/part-5-06.mp3', 19, 297631),
(5, 7, E'Control del entorno, interferencias, emergencias y normativa', E'Interferencias durante mantenimiento y reparación', E'Antes de reparar, operador y mantenimiento deben acordar quién controla la máquina, qué energías quedan aisladas y cuándo se retira cada bloqueo. Si una prueba requiere movimiento, delimite la zona y designe una persona responsable. Tras la intervención, realice una entrega e inspección funcional.', E'Antes de reparar, operador y mantenimiento deben acordar quién controla la máquina, qué energías quedan aisladas y cuándo se retira cada bloqueo. Si una prueba requiere movimiento, delimite la zona y designe una persona responsable. Tras la intervención, realice una entrega e inspección funcional. En la aplicación práctica deben respetarse el manual del fabricante, las disposiciones internas de seguridad y el criterio de parada indicado.', array[E'Antes de reparar, operador y mantenimiento deben acordar quién controla la máquina, qué energías quedan…', E'Si una prueba requiere movimiento, delimite la zona y designe una persona responsable', E'Tras la intervención, realice una entrega e inspección funcional']::text[], E'Si una prueba requiere movimiento, delimite la zona y designe una persona responsable.', E'ET 2001-1-08 · 3.3.5 · Presentación Cursos Pedro', E'consulta general', E'{courseVersionId}/block-5/audio/part-5-07.mp3', 20, 311005),
(5, 8, E'Control del entorno, interferencias, emergencias y normativa', E'Incendio, primeros auxilios y conducta PAS', E'Ante un accidente aplique la conducta PAS: proteger, avisar y socorrer. Evite nuevas víctimas, active la emergencia con información precisa y ayude solo dentro de su formación. En un incendio incipiente use el extintor únicamente si dispone de una salida segura y no asume un riesgo adicional.', E'Ante un accidente aplique la conducta PAS: proteger, avisar y socorrer. Evite nuevas víctimas, active la emergencia con información precisa y ayude solo dentro de su formación. En un incendio incipiente use el extintor únicamente si dispone de una salida segura y no asume un riesgo adicional. En la aplicación práctica deben respetarse el manual del fabricante, las disposiciones internas de seguridad y el criterio de parada indicado.', array[E'Ante un accidente aplique la conducta PAS: proteger, avisar y socorrer', E'Evite nuevas víctimas, active la emergencia con información precisa y ayude solo dentro de su formación', E'En un incendio incipiente use el extintor únicamente si dispone de una salida segura y no asume un riesgo…']::text[], E'Detenga la operación y comunique cualquier condición que impida trabajar con seguridad.', E'ET 2001-1-08 · 3.3.2.b · Presentación Cursos Pedro', E'consulta general', E'{courseVersionId}/block-5/audio/part-5-08.mp3', 20, 313931),
(5, 9, E'Control del entorno, interferencias, emergencias y normativa', E'Plan de emergencia y evacuación', E'Conozca las alarmas, comunicaciones, vías de evacuación y puntos de reunión. Sepa cómo dejar la máquina sin bloquear una pista y cómo informar de su ubicación. No improvise rutas por frentes o zonas de tráfico. Después de un incidente, informe y colabore para evitar que vuelva a repetirse.', E'Conozca las alarmas, comunicaciones, vías de evacuación y puntos de reunión. Sepa cómo dejar la máquina sin bloquear una pista y cómo informar de su ubicación. No improvise rutas por frentes o zonas de tráfico. Después de un incidente, informe y colabore para evitar que vuelva a repetirse. En la aplicación práctica deben respetarse el manual del fabricante, las disposiciones internas de seguridad y el criterio de parada indicado.', array[E'Conozca las alarmas, comunicaciones, vías de evacuación y puntos de reunión', E'Sepa cómo dejar la máquina sin bloquear una pista y cómo informar de su ubicación', E'No improvise rutas por frentes o zonas de tráfico']::text[], E'No improvise rutas por frentes o zonas de tráfico.', E'ET 2001-1-08 · 3.3.2.b · Presentación Cursos Pedro', E'consulta general', E'{courseVersionId}/block-5/audio/part-5-09.mp3', 16, 254999),
(5, 10, E'Control del entorno, interferencias, emergencias y normativa', E'Marco normativo, derechos y obligaciones', E'Esta formación de actualización se encuadra en la ITC 02.1.02 y en la Especificación Técnica 2001-1-08. Para este puesto, la especificación fija una frecuencia máxima obligatoria de dos años. Respete el manual, las disposiciones internas y comunique cualquier situación de riesgo grave.', E'Esta formación de actualización se encuadra en la ITC 02.1.02 y en la Especificación Técnica 2001-1-08. Para este puesto, la especificación fija una frecuencia máxima obligatoria de dos años. Respete el manual, las disposiciones internas y comunique cualquier situación de riesgo grave. En la aplicación práctica deben respetarse el manual del fabricante, las disposiciones internas de seguridad y el criterio de parada indicado.', array[E'Esta formación de actualización se encuadra en la ITC 02.1.02 y en la Especificación Técnica 2001-1-08', E'Para este puesto, la especificación fija una frecuencia máxima obligatoria de dos años', E'Respete el manual, las disposiciones internas y comunique cualquier situación de riesgo grave']::text[], E'Respete el manual, las disposiciones internas y comunique cualquier situación de riesgo grave.', E'ITC 02.1.02 · ET 2001-1-08, 3.4 · BOE consolidado', E'consulta general', E'{courseVersionId}/block-5/audio/part-5-10.mp3', 20, 312259);

create temporary table course_one_slides (
  block_position integer not null,
  segment_position integer not null,
  slide_position integer not null,
  title text not null,
  body text not null,
  storage_path text not null,
  source_label text not null,
  source_page text not null,
  alt_text text not null,
  primary key (block_position, segment_position, slide_position)
) on commit drop;

insert into course_one_slides values
(1, 1, 1, E'Introducción al movimiento de tierras en explotaciones', E'El movimiento de tierras reúne las operaciones necesarias para modificar el terreno en una explotación. El ciclo principal comprende el arranque, la carga, el transporte y la descarga, y puede completarse con extendido, nivelación, compactación y refino.', E'course-1/5h/block-1/slides/audio-1-01-slide-01.png', E'Presentación Cursos Pedro y desarrollo didáctico Inmíner', E'Diapositiva original 4', E'Explicación visual de la parte 1.1: Introducción al movimiento de tierras en explotaciones'),
(1, 1, 2, E'Aplicación segura · Introducción al movimiento de tierras en explotaciones', E'1. El movimiento de tierras reúne las operaciones necesarias para modificar el terreno en una explotación\n2. El ciclo principal comprende el arranque, la carga, el transporte y la descarga, y puede completarse con…\n3. Aplicar el manual del fabricante y las disposiciones internas\n\nCriterio de parada: Detenga la operación y comunique cualquier condición que impida trabajar con seguridad.', E'course-1/5h/block-1/slides/audio-1-01-slide-02.png', E'Presentación Cursos Pedro y desarrollo didáctico Inmíner', E'Diapositiva original 4', E'Aplicación segura de la parte 1.1: Introducción al movimiento de tierras en explotaciones'),
(1, 2, 1, E'La fase de arranque: concepto y objetivos principales', E'El arranque es la primera fase del ciclo. Su objetivo es separar el material del macizo o del terreno natural y dejarlo en condiciones adecuadas para su carga. El método depende de la naturaleza, dureza y estado del material.', E'course-1/5h/block-1/slides/audio-1-02-slide-01.png', E'Presentación Cursos Pedro y desarrollo didáctico Inmíner', E'Diapositiva original 5', E'Explicación visual de la parte 1.2: La fase de arranque: concepto y objetivos principales'),
(1, 2, 2, E'Aplicación segura · La fase de arranque: concepto y objetivos principales', E'1. El arranque es la primera fase del ciclo\n2. Su objetivo es separar el material del macizo o del terreno natural y dejarlo en condiciones adecuadas para su…\n3. El método depende de la naturaleza, dureza y estado del material\n\nCriterio de parada: Detenga la operación y comunique cualquier condición que impida trabajar con seguridad.', E'course-1/5h/block-1/slides/audio-1-02-slide-02.png', E'Presentación Cursos Pedro y desarrollo didáctico Inmíner', E'Diapositiva original 5', E'Aplicación segura de la parte 1.2: La fase de arranque: concepto y objetivos principales'),
(1, 3, 1, E'Métodos de arranque: uso de voladuras y perforación', E'Cuando la roca sana presenta elevada dureza, el arranque suele requerir perforación y voladura. La operación debe planificarse para obtener la fragmentación necesaria, limitar proyecciones y vibraciones y facilitar las fases posteriores.', E'course-1/5h/block-1/slides/audio-1-03-slide-01.png', E'Presentación Cursos Pedro y desarrollo didáctico Inmíner', E'Diapositiva original 5', E'Explicación visual de la parte 1.3: Métodos de arranque: uso de voladuras y perforación'),
(1, 3, 2, E'Aplicación segura · Métodos de arranque: uso de voladuras y perforación', E'1. Cuando la roca sana presenta elevada dureza, el arranque suele requerir perforación y voladura\n2. La operación debe planificarse para obtener la fragmentación necesaria, limitar proyecciones y vibraciones y…\n3. Aplicar el manual del fabricante y las disposiciones internas\n\nCriterio de parada: Detenga la operación y comunique cualquier condición que impida trabajar con seguridad.', E'course-1/5h/block-1/slides/audio-1-03-slide-02.png', E'Presentación Cursos Pedro y desarrollo didáctico Inmíner', E'Diapositiva original 5', E'Aplicación segura de la parte 1.3: Métodos de arranque: uso de voladuras y perforación'),
(1, 4, 1, E'El arranque mecánico mediante tractor de cadenas y ripper', E'Los materiales ripables pueden arrancarse mecánicamente con un tractor de cadenas provisto de escarificador o ripper. La penetración de los dientes y el empuje del tractor rompen y aflojan el terreno sin recurrir a explosivos.', E'course-1/5h/block-1/slides/audio-1-04-slide-01.png', E'Presentación Cursos Pedro y desarrollo didáctico Inmíner', E'Diapositiva original 5', E'Explicación visual de la parte 1.4: El arranque mecánico mediante tractor de cadenas y ripper'),
(1, 4, 2, E'Aplicación segura · El arranque mecánico mediante tractor de cadenas y ripper', E'1. Los materiales ripables pueden arrancarse mecánicamente con un tractor de cadenas provisto de escarificador o…\n2. La penetración de los dientes y el empuje del tractor rompen y aflojan el terreno sin recurrir a explosivos\n3. Aplicar el manual del fabricante y las disposiciones internas\n\nCriterio de parada: Detenga la operación y comunique cualquier condición que impida trabajar con seguridad.', E'course-1/5h/block-1/slides/audio-1-04-slide-02.png', E'Presentación Cursos Pedro y desarrollo didáctico Inmíner', E'Diapositiva original 10', E'Aplicación segura de la parte 1.4: El arranque mecánico mediante tractor de cadenas y ripper'),
(1, 5, 1, E'La fase de carga: introducción y equipos habituales', E'La carga recoge el material arrancado y lo deposita en el equipo de transporte o en la instalación receptora. Entre los equipos habituales se encuentran la pala cargadora y la excavadora, seleccionadas según frente, producción y compatibilidad con el transporte.', E'course-1/5h/block-1/slides/audio-1-05-slide-01.png', E'Presentación Cursos Pedro y desarrollo didáctico Inmíner', E'Diapositiva original 6', E'Explicación visual de la parte 1.5: La fase de carga: introducción y equipos habituales'),
(1, 5, 2, E'Aplicación segura · La fase de carga: introducción y equipos habituales', E'1. La carga recoge el material arrancado y lo deposita en el equipo de transporte o en la instalación receptora\n2. Entre los equipos habituales se encuentran la pala cargadora y la excavadora, seleccionadas según frente,…\n3. Aplicar el manual del fabricante y las disposiciones internas\n\nCriterio de parada: Detenga la operación y comunique cualquier condición que impida trabajar con seguridad.', E'course-1/5h/block-1/slides/audio-1-05-slide-02.png', E'Presentación Cursos Pedro y desarrollo didáctico Inmíner', E'Diapositiva original 11', E'Aplicación segura de la parte 1.5: La fase de carga: introducción y equipos habituales'),
(1, 6, 1, E'Características operativas de la pala cargadora sobre ruedas', E'La pala cargadora sobre ruedas destaca por su movilidad, rapidez de desplazamiento y versatilidad en firmes adecuados. Su rendimiento exige controlar el estado del terreno, la estabilidad, los neumáticos y la posición segura del cucharón durante la circulación.', E'course-1/5h/block-1/slides/audio-1-06-slide-01.png', E'Presentación Cursos Pedro y desarrollo didáctico Inmíner', E'Diapositiva original 6', E'Explicación visual de la parte 1.6: Características operativas de la pala cargadora sobre ruedas'),
(1, 6, 2, E'Aplicación segura · Características operativas de la pala cargadora sobre ruedas', E'1. La pala cargadora sobre ruedas destaca por su movilidad, rapidez de desplazamiento y versatilidad en firmes…\n2. Su rendimiento exige controlar el estado del terreno, la estabilidad, los neumáticos y la posición segura del…\n3. Aplicar el manual del fabricante y las disposiciones internas\n\nCriterio de parada: Detenga la operación y comunique cualquier condición que impida trabajar con seguridad.', E'course-1/5h/block-1/slides/audio-1-06-slide-02.png', E'Presentación Cursos Pedro y desarrollo didáctico Inmíner', E'Diapositiva original 12', E'Aplicación segura de la parte 1.6: Características operativas de la pala cargadora sobre ruedas'),
(1, 7, 1, E'Análisis de costes y distancias en la fase de transporte', E'El transporte suele tener un peso decisivo en el coste del movimiento de tierras. La distancia, las diferencias de cota, el estado y pendiente de las pistas, la capacidad del equipo y los tiempos de espera determinan el rendimiento del ciclo.', E'course-1/5h/block-1/slides/audio-1-07-slide-01.png', E'Presentación Cursos Pedro y desarrollo didáctico Inmíner', E'Diapositiva original 7', E'Explicación visual de la parte 1.7: Análisis de costes y distancias en la fase de transporte'),
(1, 7, 2, E'Aplicación segura · Análisis de costes y distancias en la fase de transporte', E'1. El transporte suele tener un peso decisivo en el coste del movimiento de tierras\n2. La distancia, las diferencias de cota, el estado y pendiente de las pistas, la capacidad del equipo y los…\n3. Aplicar el manual del fabricante y las disposiciones internas\n\nCriterio de parada: Detenga la operación y comunique cualquier condición que impida trabajar con seguridad.', E'course-1/5h/block-1/slides/audio-1-07-slide-02.png', E'Presentación Cursos Pedro y desarrollo didáctico Inmíner', E'Diapositiva original 88', E'Aplicación segura de la parte 1.7: Análisis de costes y distancias en la fase de transporte'),
(1, 8, 1, E'Tipos de transporte y descarga en tolva o escombrera', E'El material puede transportarse con volquetes, dúmperes, camiones bañera u otros sistemas continuos. La descarga puede realizarse en tolvas, acopios o escombreras y requiere una zona estable, señalizada y compatible con el equipo.', E'course-1/5h/block-1/slides/audio-1-08-slide-01.png', E'Presentación Cursos Pedro y desarrollo didáctico Inmíner', E'Diapositiva original 8', E'Explicación visual de la parte 1.8: Tipos de transporte y descarga en tolva o escombrera'),
(1, 8, 2, E'Aplicación segura · Tipos de transporte y descarga en tolva o escombrera', E'1. El material puede transportarse con volquetes, dúmperes, camiones bañera u otros sistemas continuos\n2. La descarga puede realizarse en tolvas, acopios o escombreras y requiere una zona estable, señalizada y…\n3. Aplicar el manual del fabricante y las disposiciones internas\n\nCriterio de parada: Detenga la operación y comunique cualquier condición que impida trabajar con seguridad.', E'course-1/5h/block-1/slides/audio-1-08-slide-02.png', E'Presentación Cursos Pedro y desarrollo didáctico Inmíner', E'Diapositiva original 89', E'Aplicación segura de la parte 1.8: Tipos de transporte y descarga en tolva o escombrera'),
(1, 9, 1, E'Extendido, nivelación, compactación y refino', E'Después de la descarga pueden ser necesarias operaciones de extendido, nivelación, compactación y refino. Estas fases colocan el material con la geometría, espesor, densidad y acabado previstos en el proyecto.', E'course-1/5h/block-1/slides/audio-1-09-slide-01.png', E'Presentación Cursos Pedro y desarrollo didáctico Inmíner', E'Diapositiva original 9', E'Explicación visual de la parte 1.9: Extendido, nivelación, compactación y refino'),
(1, 9, 2, E'Aplicación segura · Extendido, nivelación, compactación y refino', E'1. Después de la descarga pueden ser necesarias operaciones de extendido, nivelación, compactación y refino\n2. Estas fases colocan el material con la geometría, espesor, densidad y acabado previstos en el proyecto\n3. Aplicar el manual del fabricante y las disposiciones internas\n\nCriterio de parada: Detenga la operación y comunique cualquier condición que impida trabajar con seguridad.', E'course-1/5h/block-1/slides/audio-1-09-slide-02.png', E'Presentación Cursos Pedro y desarrollo didáctico Inmíner', E'Diapositiva original 11', E'Aplicación segura de la parte 1.9: Extendido, nivelación, compactación y refino'),
(1, 10, 1, E'Sistemas mixtos: excavadora, pala y mototraílla', E'Los sistemas mixtos combinan varias funciones en una misma máquina. La excavadora puede arrancar y cargar, la pala puede cargar y realizar transporte corto y la mototraílla puede arrancar, cargar, transportar, descargar y extender en condiciones adecuadas.', E'course-1/5h/block-1/slides/audio-1-10-slide-01.png', E'Presentación Cursos Pedro y desarrollo didáctico Inmíner', E'Diapositiva original 10', E'Explicación visual de la parte 1.10: Sistemas mixtos: excavadora, pala y mototraílla'),
(1, 10, 2, E'Aplicación segura · Sistemas mixtos: excavadora, pala y mototraílla', E'1. Los sistemas mixtos combinan varias funciones en una misma máquina\n2. La excavadora puede arrancar y cargar, la pala puede cargar y realizar transporte corto y la mototraílla puede…\n3. Aplicar el manual del fabricante y las disposiciones internas\n\nCriterio de parada: Detenga la operación y comunique cualquier condición que impida trabajar con seguridad.', E'course-1/5h/block-1/slides/audio-1-10-slide-02.png', E'Presentación Cursos Pedro y desarrollo didáctico Inmíner', E'Diapositiva original 11', E'Aplicación segura de la parte 1.10: Sistemas mixtos: excavadora, pala y mototraílla'),
(2, 1, 1, E'Preparación personal y equipos de protección', E'Antes de acceder a la máquina, compruebe que se encuentra en condiciones físicas y mentales adecuadas. Utilice ropa ajustada, calzado de seguridad, casco y los EPI definidos para el riesgo, sin olvidar que complementan, pero no sustituyen, las protecciones colectivas.', E'course-1/5h/block-2/slides/audio-2-01-slide-01.png', E'Presentación Cursos Pedro y desarrollo didáctico Inmíner', E'Diapositiva original 13', E'Explicación visual de la parte 2.1: Preparación personal y equipos de protección'),
(2, 1, 2, E'Aplicación segura · Preparación personal y equipos de protección', E'1. Antes de acceder a la máquina, compruebe que se encuentra en condiciones físicas y mentales adecuadas\n2. Utilice ropa ajustada, calzado de seguridad, casco y los EPI definidos para el riesgo, sin olvidar que…\n3. Aplicar el manual del fabricante y las disposiciones internas\n\nCriterio de parada: Detenga la operación y comunique cualquier condición que impida trabajar con seguridad.', E'course-1/5h/block-2/slides/audio-2-01-slide-02.png', E'Presentación Cursos Pedro y desarrollo didáctico Inmíner', E'Diapositiva original 44', E'Aplicación segura de la parte 2.1: Preparación personal y equipos de protección'),
(2, 2, 1, E'Inspección perimetral de la máquina', E'La revisión diaria comienza desde el suelo y con la máquina inmovilizada. Recorra todo el perímetro buscando personas, obstáculos, daños, fugas, piezas sueltas y acumulaciones de material. Registre cualquier anomalía y valórala antes del arranque.', E'course-1/5h/block-2/slides/audio-2-02-slide-01.png', E'Presentación Cursos Pedro y desarrollo didáctico Inmíner', E'Diapositiva original 14', E'Explicación visual de la parte 2.2: Inspección perimetral de la máquina'),
(2, 2, 2, E'Aplicación segura · Inspección perimetral de la máquina', E'1. La revisión diaria comienza desde el suelo y con la máquina inmovilizada\n2. Recorra todo el perímetro buscando personas, obstáculos, daños, fugas, piezas sueltas y acumulaciones de…\n3. Registre cualquier anomalía y valórala antes del arranque\n\nCriterio de parada: Detenga la operación y comunique cualquier condición que impida trabajar con seguridad.', E'course-1/5h/block-2/slides/audio-2-02-slide-02.png', E'Presentación Cursos Pedro y desarrollo didáctico Inmíner', E'Diapositiva original 22', E'Aplicación segura de la parte 2.2: Inspección perimetral de la máquina'),
(2, 3, 1, E'Niveles, fugas y circuitos calientes', E'Compruebe los niveles con la máquina en la posición indicada por el fabricante. Nunca abra en caliente el circuito de refrigeración ni busque una fuga hidráulica con la mano. Si detecta combustible, una manguera dañada o una pérdida importante, inmovilice la máquina y comuníquelo.', E'course-1/5h/block-2/slides/audio-2-03-slide-01.png', E'Presentación Cursos Pedro y desarrollo didáctico Inmíner', E'Diapositiva original 23', E'Explicación visual de la parte 2.3: Niveles, fugas y circuitos calientes'),
(2, 3, 2, E'Aplicación segura · Niveles, fugas y circuitos calientes', E'1. Compruebe los niveles con la máquina en la posición indicada por el fabricante\n2. Nunca abra en caliente el circuito de refrigeración ni busque una fuga hidráulica con la mano\n3. Si detecta combustible, una manguera dañada o una pérdida importante, inmovilice la máquina y comuníquelo\n\nCriterio de parada: Si detecta combustible, una manguera dañada o una pérdida importante, inmovilice la máquina y comuníquelo.', E'course-1/5h/block-2/slides/audio-2-03-slide-02.png', E'Presentación Cursos Pedro y desarrollo didáctico Inmíner', E'Diapositiva original 24', E'Aplicación segura de la parte 2.3: Niveles, fugas y circuitos calientes'),
(2, 4, 1, E'Neumáticos y tren de rodaje', E'En palas, revise presión, cortes, desgaste, llantas y fijaciones. En máquinas de cadenas, compruebe tejas, rodillos, rueda motriz y tensión aparente. No retire piedras ni intervenga en ruedas o cadenas sin detener, asegurar y aplicar el procedimiento previsto para esa operación.', E'course-1/5h/block-2/slides/audio-2-04-slide-01.png', E'Presentación Cursos Pedro y desarrollo didáctico Inmíner', E'Diapositiva original 22', E'Explicación visual de la parte 2.4: Neumáticos y tren de rodaje'),
(2, 4, 2, E'Aplicación segura · Neumáticos y tren de rodaje', E'1. En palas, revise presión, cortes, desgaste, llantas y fijaciones\n2. En máquinas de cadenas, compruebe tejas, rodillos, rueda motriz y tensión aparente\n3. No retire piedras ni intervenga en ruedas o cadenas sin detener, asegurar y aplicar el procedimiento previsto…\n\nCriterio de parada: Detenga la operación y comunique cualquier condición que impida trabajar con seguridad.', E'course-1/5h/block-2/slides/audio-2-04-slide-02.png', E'Presentación Cursos Pedro y desarrollo didáctico Inmíner', E'Diapositiva original 81', E'Aplicación segura de la parte 2.4: Neumáticos y tren de rodaje'),
(2, 5, 1, E'Equipo de trabajo y sistema hidráulico', E'Inspeccione cucharón, hoja, pluma, pasadores, dientes, cilindros y latiguillos. Una fisura o una fuga puede provocar pérdida de control o caída del accesorio. Nadie debe situarse bajo un equipo elevado sin bloqueo mecánico; para revisar, apoye el equipo y descargue la presión residual.', E'course-1/5h/block-2/slides/audio-2-05-slide-01.png', E'Presentación Cursos Pedro y desarrollo didáctico Inmíner', E'Diapositiva original 23', E'Explicación visual de la parte 2.5: Equipo de trabajo y sistema hidráulico'),
(2, 5, 2, E'Aplicación segura · Equipo de trabajo y sistema hidráulico', E'1. Inspeccione cucharón, hoja, pluma, pasadores, dientes, cilindros y latiguillos\n2. Una fisura o una fuga puede provocar pérdida de control o caída del accesorio\n3. Nadie debe situarse bajo un equipo elevado sin bloqueo mecánico; para revisar, apoye el equipo y descargue la…\n\nCriterio de parada: Detenga la operación y comunique cualquier condición que impida trabajar con seguridad.', E'course-1/5h/block-2/slides/audio-2-05-slide-02.png', E'Presentación Cursos Pedro y desarrollo didáctico Inmíner', E'Diapositiva original 81', E'Aplicación segura de la parte 2.5: Equipo de trabajo y sistema hidráulico'),
(2, 6, 1, E'Acceso seguro y acondicionamiento de la cabina', E'Suba y baje mirando hacia la máquina y manteniendo tres puntos de apoyo. Limpie peldaños y asideros, ajuste asiento y espejos, retire objetos sueltos y compruebe la salida de emergencia. Abróchese el cinturón antes de mover el equipo y no salte nunca desde la cabina.', E'course-1/5h/block-2/slides/audio-2-06-slide-01.png', E'Presentación Cursos Pedro y desarrollo didáctico Inmíner', E'Diapositiva original 25', E'Explicación visual de la parte 2.6: Acceso seguro y acondicionamiento de la cabina'),
(2, 6, 2, E'Aplicación segura · Acceso seguro y acondicionamiento de la cabina', E'1. Suba y baje mirando hacia la máquina y manteniendo tres puntos de apoyo\n2. Limpie peldaños y asideros, ajuste asiento y espejos, retire objetos sueltos y compruebe la salida de emergencia\n3. Abróchese el cinturón antes de mover el equipo y no salte nunca desde la cabina\n\nCriterio de parada: Abróchese el cinturón antes de mover el equipo y no salte nunca desde la cabina.', E'course-1/5h/block-2/slides/audio-2-06-slide-02.png', E'Presentación Cursos Pedro y desarrollo didáctico Inmíner', E'Diapositiva original 25', E'Aplicación segura de la parte 2.6: Acceso seguro y acondicionamiento de la cabina'),
(2, 7, 1, E'Comprobaciones funcionales antes de desplazarse', E'Después del arranque, observe el panel y pruebe frenos, dirección, bocina, alarma de retroceso, luces y mandos en una zona segura y a baja velocidad. Atienda a ruidos, vibraciones o respuestas lentas. Una alarma no se anula para continuar: se identifica la causa y se aplica el procedimiento.', E'course-1/5h/block-2/slides/audio-2-07-slide-01.png', E'Presentación Cursos Pedro y desarrollo didáctico Inmíner', E'Diapositiva original 14', E'Explicación visual de la parte 2.7: Comprobaciones funcionales antes de desplazarse'),
(2, 7, 2, E'Aplicación segura · Comprobaciones funcionales antes de desplazarse', E'1. Después del arranque, observe el panel y pruebe frenos, dirección, bocina, alarma de retroceso, luces y mandos…\n2. Atienda a ruidos, vibraciones o respuestas lentas\n3. Una alarma no se anula para continuar: se identifica la causa y se aplica el procedimiento\n\nCriterio de parada: Detenga la operación y comunique cualquier condición que impida trabajar con seguridad.', E'course-1/5h/block-2/slides/audio-2-07-slide-02.png', E'Presentación Cursos Pedro y desarrollo didáctico Inmíner', E'Diapositiva original 86', E'Aplicación segura de la parte 2.7: Comprobaciones funcionales antes de desplazarse'),
(2, 8, 1, E'Mantenimiento básico, bloqueo y consignación', E'Antes de una intervención, estacione en terreno firme, apoye el equipo, accione el freno, detenga el motor y controle la llave. Si existe energía eléctrica, hidráulica, neumática, mecánica o térmica, bloquee, consigne y verifique su ausencia. Nunca confíe solo en los cilindros hidráulicos.', E'course-1/5h/block-2/slides/audio-2-08-slide-01.png', E'Presentación Cursos Pedro y desarrollo didáctico Inmíner', E'Diapositiva original 26', E'Explicación visual de la parte 2.8: Mantenimiento básico, bloqueo y consignación'),
(2, 8, 2, E'Aplicación segura · Mantenimiento básico, bloqueo y consignación', E'1. Antes de una intervención, estacione en terreno firme, apoye el equipo, accione el freno, detenga el motor y…\n2. Si existe energía eléctrica, hidráulica, neumática, mecánica o térmica, bloquee, consigne y verifique su…\n3. Nunca confíe solo en los cilindros hidráulicos\n\nCriterio de parada: Nunca confíe solo en los cilindros hidráulicos.', E'course-1/5h/block-2/slides/audio-2-08-slide-02.png', E'Presentación Cursos Pedro y desarrollo didáctico Inmíner', E'Diapositiva original 39', E'Aplicación segura de la parte 2.8: Mantenimiento básico, bloqueo y consignación'),
(2, 9, 1, E'Cambio seguro de accesorios', E'Cambie cucharas u otros accesorios sobre una superficie estable, sin personas alrededor y siguiendo la secuencia del fabricante. Libere la presión antes de desconectar circuitos. Tras el montaje, verifique pasadores, conexiones e indicadores de bloqueo y haga una prueba próxima al suelo.', E'course-1/5h/block-2/slides/audio-2-09-slide-01.png', E'Presentación Cursos Pedro y desarrollo didáctico Inmíner', E'Diapositiva original 31', E'Explicación visual de la parte 2.9: Cambio seguro de accesorios'),
(2, 9, 2, E'Aplicación segura · Cambio seguro de accesorios', E'1. Cambie cucharas u otros accesorios sobre una superficie estable, sin personas alrededor y siguiendo la…\n2. Libere la presión antes de desconectar circuitos\n3. Tras el montaje, verifique pasadores, conexiones e indicadores de bloqueo y haga una prueba próxima al suelo\n\nCriterio de parada: Detenga la operación y comunique cualquier condición que impida trabajar con seguridad.', E'course-1/5h/block-2/slides/audio-2-09-slide-02.png', E'Presentación Cursos Pedro y desarrollo didáctico Inmíner', E'Diapositiva original 32', E'Aplicación segura de la parte 2.9: Cambio seguro de accesorios'),
(2, 10, 1, E'Embarque, transporte, remolcado y recuperación', E'El embarque y el remolcado requieren un plan, medios certificados y puntos de amarre o anclaje previstos por el fabricante. Mantenga despejada la zona de posible latigazo de cables y eslingas. Si la máquina está hundida, en pendiente o junto a un borde, estabilice primero la situación.', E'course-1/5h/block-2/slides/audio-2-10-slide-01.png', E'Presentación Cursos Pedro y desarrollo didáctico Inmíner', E'Diapositiva original 29', E'Explicación visual de la parte 2.10: Embarque, transporte, remolcado y recuperación'),
(2, 10, 2, E'Aplicación segura · Embarque, transporte, remolcado y recuperación', E'1. El embarque y el remolcado requieren un plan, medios certificados y puntos de amarre o anclaje previstos por…\n2. Mantenga despejada la zona de posible latigazo de cables y eslingas\n3. Si la máquina está hundida, en pendiente o junto a un borde, estabilice primero la situación\n\nCriterio de parada: Si la máquina está hundida, en pendiente o junto a un borde, estabilice primero la situación.', E'course-1/5h/block-2/slides/audio-2-10-slide-02.png', E'Presentación Cursos Pedro y desarrollo didáctico Inmíner', E'Diapositiva original 30', E'Aplicación segura de la parte 2.10: Embarque, transporte, remolcado y recuperación'),
(3, 1, 1, E'Arranque, calentamiento y preparación operativa', E'Arranque siempre desde el puesto del operador, con los mandos neutralizados y el entorno despejado. Durante el calentamiento vigile presión de aceite, temperatura y mensajes del panel. Si aparecen humo anormal, golpes o una alarma persistente, detenga la máquina e informe antes de trabajar.', E'course-1/5h/block-3/slides/audio-3-01-slide-01.png', E'Presentación Cursos Pedro y desarrollo didáctico Inmíner', E'Diapositiva original 14', E'Explicación visual de la parte 3.1: Arranque, calentamiento y preparación operativa'),
(3, 1, 2, E'Aplicación segura · Arranque, calentamiento y preparación operativa', E'1. Arranque siempre desde el puesto del operador, con los mandos neutralizados y el entorno despejado\n2. Durante el calentamiento vigile presión de aceite, temperatura y mensajes del panel\n3. Si aparecen humo anormal, golpes o una alarma persistente, detenga la máquina e informe antes de trabajar\n\nCriterio de parada: Si aparecen humo anormal, golpes o una alarma persistente, detenga la máquina e informe antes de trabajar.', E'course-1/5h/block-3/slides/audio-3-01-slide-02.png', E'Presentación Cursos Pedro y desarrollo didáctico Inmíner', E'Diapositiva original 86', E'Aplicación segura de la parte 3.1: Arranque, calentamiento y preparación operativa'),
(3, 2, 1, E'Visibilidad, zonas ciegas y control del área', E'Cámaras, espejos y alarmas ayudan, pero no eliminan las zonas ciegas. Antes de moverse, observe, avise y espere. Si la maniobra necesita un señalista, manténgalo siempre visible y utilice señales acordadas. Si pierde el contacto, detenga inmediatamente la máquina.', E'course-1/5h/block-3/slides/audio-3-02-slide-01.png', E'Presentación Cursos Pedro y desarrollo didáctico Inmíner', E'Diapositiva original 83', E'Explicación visual de la parte 3.2: Visibilidad, zonas ciegas y control del área'),
(3, 2, 2, E'Aplicación segura · Visibilidad, zonas ciegas y control del área', E'1. Cámaras, espejos y alarmas ayudan, pero no eliminan las zonas ciegas\n2. Antes de moverse, observe, avise y espere\n3. Si la maniobra necesita un señalista, manténgalo siempre visible y utilice señales acordadas\n\nCriterio de parada: Si pierde el contacto, detenga inmediatamente la máquina.', E'course-1/5h/block-3/slides/audio-3-02-slide-02.png', E'Presentación Cursos Pedro y desarrollo didáctico Inmíner', E'Diapositiva original 87', E'Aplicación segura de la parte 3.2: Visibilidad, zonas ciegas y control del área'),
(3, 3, 1, E'Carga segura con pala cargadora', E'Aproxímese al acopio con el cucharón bajo y los bastidores alineados. Llene sin embestir, retroceda mirando la trayectoria y transporte la carga baja y estable. Al descargar sobre un camión, no golpee la caja ni pase sobre la cabina, y distribuya el material de forma uniforme.', E'course-1/5h/block-3/slides/audio-3-03-slide-01.png', E'Presentación Cursos Pedro y desarrollo didáctico Inmíner', E'Diapositiva original 15', E'Explicación visual de la parte 3.3: Carga segura con pala cargadora'),
(3, 3, 2, E'Aplicación segura · Carga segura con pala cargadora', E'1. Aproxímese al acopio con el cucharón bajo y los bastidores alineados\n2. Llene sin embestir, retroceda mirando la trayectoria y transporte la carga baja y estable\n3. Al descargar sobre un camión, no golpee la caja ni pase sobre la cabina, y distribuya el material de forma…\n\nCriterio de parada: Al descargar sobre un camión, no golpee la caja ni pase sobre la cabina, y distribuya el material de forma uniforme.', E'course-1/5h/block-3/slides/audio-3-03-slide-02.png', E'Presentación Cursos Pedro y desarrollo didáctico Inmíner', E'Diapositiva original 16', E'Aplicación segura de la parte 3.3: Carga segura con pala cargadora'),
(3, 4, 1, E'Excavación y carga con excavadora hidráulica', E'Trabaje desde una plataforma resistente y con el radio de giro despejado. Identifique servicios enterrados y evalúe el frente o la zanja. Coloque el camión fuera de la caída de material y evite pasar la cuchara sobre su cabina. Si pierde visibilidad o comunicación, detenga el ciclo.', E'course-1/5h/block-3/slides/audio-3-04-slide-01.png', E'Presentación Cursos Pedro y desarrollo didáctico Inmíner', E'Diapositiva original 18', E'Explicación visual de la parte 3.4: Excavación y carga con excavadora hidráulica'),
(3, 4, 2, E'Aplicación segura · Excavación y carga con excavadora hidráulica', E'1. Trabaje desde una plataforma resistente y con el radio de giro despejado\n2. Identifique servicios enterrados y evalúe el frente o la zanja\n3. Coloque el camión fuera de la caída de material y evite pasar la cuchara sobre su cabina\n\nCriterio de parada: Si pierde visibilidad o comunicación, detenga el ciclo.', E'course-1/5h/block-3/slides/audio-3-04-slide-02.png', E'Presentación Cursos Pedro y desarrollo didáctico Inmíner', E'Diapositiva original 19', E'Aplicación segura de la parte 3.4: Excavación y carga con excavadora hidráulica'),
(3, 5, 1, E'Operación segura con tractor de cadenas', E'En pendientes, trabaje según la dirección definida por el fabricante y evite giros bruscos o desplazamientos laterales. Lleve la hoja baja y mantenga distancia a bordes y coronaciones. Si aparecen vibraciones, pérdida de control o una resistencia imprevista, detenga la operación.', E'course-1/5h/block-3/slides/audio-3-05-slide-01.png', E'Presentación Cursos Pedro y desarrollo didáctico Inmíner', E'Diapositiva original 16', E'Explicación visual de la parte 3.5: Operación segura con tractor de cadenas'),
(3, 5, 2, E'Aplicación segura · Operación segura con tractor de cadenas', E'1. En pendientes, trabaje según la dirección definida por el fabricante y evite giros bruscos o desplazamientos…\n2. Lleve la hoja baja y mantenga distancia a bordes y coronaciones\n3. Si aparecen vibraciones, pérdida de control o una resistencia imprevista, detenga la operación\n\nCriterio de parada: Si aparecen vibraciones, pérdida de control o una resistencia imprevista, detenga la operación.', E'course-1/5h/block-3/slides/audio-3-05-slide-02.png', E'Presentación Cursos Pedro y desarrollo didáctico Inmíner', E'Diapositiva original 17', E'Aplicación segura de la parte 3.5: Operación segura con tractor de cadenas'),
(3, 6, 1, E'Circulación por pistas, rampas y cruces', E'Adapte la velocidad a la carga, visibilidad, pendiente, firme y tráfico. Respete sentidos, prioridades y distancias de seguridad de las disposiciones internas. En rampas no circule en punto muerto y use la relación recomendada. Polvo, lluvia, barro o baches obligan a reducir la marcha.', E'course-1/5h/block-3/slides/audio-3-06-slide-01.png', E'Presentación Cursos Pedro y desarrollo didáctico Inmíner', E'Diapositiva original 88', E'Explicación visual de la parte 3.6: Circulación por pistas, rampas y cruces'),
(3, 6, 2, E'Aplicación segura · Circulación por pistas, rampas y cruces', E'1. Adapte la velocidad a la carga, visibilidad, pendiente, firme y tráfico\n2. Respete sentidos, prioridades y distancias de seguridad de las disposiciones internas\n3. En rampas no circule en punto muerto y use la relación recomendada\n\nCriterio de parada: En rampas no circule en punto muerto y use la relación recomendada.', E'course-1/5h/block-3/slides/audio-3-06-slide-02.png', E'Presentación Cursos Pedro y desarrollo didáctico Inmíner', E'Diapositiva original 91', E'Aplicación segura de la parte 3.6: Circulación por pistas, rampas y cruces'),
(3, 7, 1, E'Taludes, frentes, zanjas y bordes', E'Respete las distancias de seguridad definidas según la altura, el material, la humedad y las sobrecargas. No trabaje bajo bloques o viseras sin sanear ni socave la plataforma de la máquina. Si aparecen grietas, caída de fragmentos o deformaciones, retírese e informe.', E'course-1/5h/block-3/slides/audio-3-07-slide-01.png', E'Presentación Cursos Pedro y desarrollo didáctico Inmíner', E'Diapositiva original 85', E'Explicación visual de la parte 3.7: Taludes, frentes, zanjas y bordes'),
(3, 7, 2, E'Aplicación segura · Taludes, frentes, zanjas y bordes', E'1. Respete las distancias de seguridad definidas según la altura, el material, la humedad y las sobrecargas\n2. No trabaje bajo bloques o viseras sin sanear ni socave la plataforma de la máquina\n3. Si aparecen grietas, caída de fragmentos o deformaciones, retírese e informe\n\nCriterio de parada: Si aparecen grietas, caída de fragmentos o deformaciones, retírese e informe.', E'course-1/5h/block-3/slides/audio-3-07-slide-02.png', E'Presentación Cursos Pedro y desarrollo didáctico Inmíner', E'Diapositiva original 88', E'Aplicación segura de la parte 3.7: Taludes, frentes, zanjas y bordes'),
(3, 8, 1, E'Descarga en camiones, tolvas y acopios', E'Controle la trayectoria y distribución del material durante la descarga. No sobrecargue camiones ni confíe en topes o bermas como freno. Mantenga a las personas fuera del punto de vertido. Si el material queda adherido, no dé golpes violentos: pare, aísle y aplique el procedimiento de desatasco.', E'course-1/5h/block-3/slides/audio-3-08-slide-01.png', E'Presentación Cursos Pedro y desarrollo didáctico Inmíner', E'Diapositiva original 8', E'Explicación visual de la parte 3.8: Descarga en camiones, tolvas y acopios'),
(3, 8, 2, E'Aplicación segura · Descarga en camiones, tolvas y acopios', E'1. Controle la trayectoria y distribución del material durante la descarga\n2. No sobrecargue camiones ni confíe en topes o bermas como freno\n3. Mantenga a las personas fuera del punto de vertido\n\nCriterio de parada: Si el material queda adherido, no dé golpes violentos: pare, aísle y aplique el procedimiento de desatasco.', E'course-1/5h/block-3/slides/audio-3-08-slide-02.png', E'Presentación Cursos Pedro y desarrollo didáctico Inmíner', E'Diapositiva original 89', E'Aplicación segura de la parte 3.8: Descarga en camiones, tolvas y acopios'),
(3, 9, 1, E'Elevación de cargas con maquinaria', E'Una pala o excavadora solo puede elevar cargas si el fabricante lo permite y existe un procedimiento autorizado. Conozca el peso, el radio y la capacidad de la configuración real. Use puntos y accesorios certificados, desplace la carga baja y nunca permita el paso de personas debajo.', E'course-1/5h/block-3/slides/audio-3-09-slide-01.png', E'Presentación Cursos Pedro y desarrollo didáctico Inmíner', E'Diapositiva original 17', E'Explicación visual de la parte 3.9: Elevación de cargas con maquinaria'),
(3, 9, 2, E'Aplicación segura · Elevación de cargas con maquinaria', E'1. Una pala o excavadora solo puede elevar cargas si el fabricante lo permite y existe un procedimiento autorizado\n2. Conozca el peso, el radio y la capacidad de la configuración real\n3. Use puntos y accesorios certificados, desplace la carga baja y nunca permita el paso de personas debajo\n\nCriterio de parada: Use puntos y accesorios certificados, desplace la carga baja y nunca permita el paso de personas debajo.', E'course-1/5h/block-3/slides/audio-3-09-slide-02.png', E'Presentación Cursos Pedro y desarrollo didáctico Inmíner', E'Diapositiva original 38', E'Aplicación segura de la parte 3.9: Elevación de cargas con maquinaria'),
(3, 10, 1, E'Estacionamiento, parada y comunicación de incidencias', E'Estacione en la zona designada, sobre terreno firme, con transmisión en neutro, freno aplicado y equipo completamente apoyado. Siga el enfriamiento indicado, retire la llave y cierre la cabina. Registre y comunique fugas, alarmas o golpes; si afectan a la seguridad, deje la máquina fuera de servicio.', E'course-1/5h/block-3/slides/audio-3-10-slide-01.png', E'Presentación Cursos Pedro y desarrollo didáctico Inmíner', E'Diapositiva original 14', E'Explicación visual de la parte 3.10: Estacionamiento, parada y comunicación de incidencias'),
(3, 10, 2, E'Aplicación segura · Estacionamiento, parada y comunicación de incidencias', E'1. Estacione en la zona designada, sobre terreno firme, con transmisión en neutro, freno aplicado y equipo…\n2. Siga el enfriamiento indicado, retire la llave y cierre la cabina\n3. Registre y comunique fugas, alarmas o golpes; si afectan a la seguridad, deje la máquina fuera de servicio\n\nCriterio de parada: Registre y comunique fugas, alarmas o golpes; si afectan a la seguridad, deje la máquina fuera de servicio.', E'course-1/5h/block-3/slides/audio-3-10-slide-02.png', E'Presentación Cursos Pedro y desarrollo didáctico Inmíner', E'Diapositiva original 89', E'Aplicación segura de la parte 3.10: Estacionamiento, parada y comunicación de incidencias'),
(4, 1, 1, E'Motor, refrigeración y lubricación', E'Vigile presión de aceite, temperatura del refrigerante, combustible e indicadores. Un sobrecalentamiento puede deberse a falta de nivel, radiadores obstruidos o una avería del ventilador. Detenga y diagnostique según el manual; nunca abra el circuito en caliente ni tape una alarma.', E'course-1/5h/block-4/slides/audio-4-01-slide-01.png', E'Presentación Cursos Pedro y desarrollo didáctico Inmíner', E'Diapositiva original 78', E'Explicación visual de la parte 4.1: Motor, refrigeración y lubricación'),
(4, 1, 2, E'Aplicación segura · Motor, refrigeración y lubricación', E'1. Vigile presión de aceite, temperatura del refrigerante, combustible e indicadores\n2. Un sobrecalentamiento puede deberse a falta de nivel, radiadores obstruidos o una avería del ventilador\n3. Detenga y diagnostique según el manual; nunca abra el circuito en caliente ni tape una alarma\n\nCriterio de parada: Detenga y diagnostique según el manual; nunca abra el circuito en caliente ni tape una alarma.', E'course-1/5h/block-4/slides/audio-4-01-slide-02.png', E'Presentación Cursos Pedro y desarrollo didáctico Inmíner', E'Diapositiva original 83', E'Aplicación segura de la parte 4.1: Motor, refrigeración y lubricación'),
(4, 2, 1, E'Transmisión, articulación y tracción', E'La transmisión lleva la potencia a ruedas o cadenas. En una pala, la articulación central crea una zona de aplastamiento que debe bloquearse antes de trabajar entre bastidores. Evite cambios bruscos, patinamientos y esfuerzos excesivos. Cualquier tirón, ruido o pérdida de tracción debe comunicarse.', E'course-1/5h/block-4/slides/audio-4-02-slide-01.png', E'Presentación Cursos Pedro y desarrollo didáctico Inmíner', E'Diapositiva original 79', E'Explicación visual de la parte 4.2: Transmisión, articulación y tracción'),
(4, 2, 2, E'Aplicación segura · Transmisión, articulación y tracción', E'1. La transmisión lleva la potencia a ruedas o cadenas\n2. En una pala, la articulación central crea una zona de aplastamiento que debe bloquearse antes de trabajar…\n3. Evite cambios bruscos, patinamientos y esfuerzos excesivos\n\nCriterio de parada: Detenga la operación y comunique cualquier condición que impida trabajar con seguridad.', E'course-1/5h/block-4/slides/audio-4-02-slide-02.png', E'Presentación Cursos Pedro y desarrollo didáctico Inmíner', E'Diapositiva original 80', E'Aplicación segura de la parte 4.2: Transmisión, articulación y tracción'),
(4, 3, 1, E'Sistema hidráulico y energía acumulada', E'El sistema hidráulico puede conservar presión incluso con el motor parado. Antes de intervenir, apoye el equipo, descargue la presión y bloquee los movimientos posibles. No busque fugas con la mano. Si aparecen movimientos espontáneos o el equipo baja sin orden, retire la máquina de servicio.', E'course-1/5h/block-4/slides/audio-4-03-slide-01.png', E'Presentación Cursos Pedro y desarrollo didáctico Inmíner', E'Diapositiva original 81', E'Explicación visual de la parte 4.3: Sistema hidráulico y energía acumulada'),
(4, 3, 2, E'Aplicación segura · Sistema hidráulico y energía acumulada', E'1. El sistema hidráulico puede conservar presión incluso con el motor parado\n2. Antes de intervenir, apoye el equipo, descargue la presión y bloquee los movimientos posibles\n3. No busque fugas con la mano\n\nCriterio de parada: Si aparecen movimientos espontáneos o el equipo baja sin orden, retire la máquina de servicio.', E'course-1/5h/block-4/slides/audio-4-03-slide-02.png', E'Presentación Cursos Pedro y desarrollo didáctico Inmíner', E'Diapositiva original 83', E'Aplicación segura de la parte 4.3: Sistema hidráulico y energía acumulada'),
(4, 4, 1, E'Equipos de trabajo, accesorios y capacidades', E'Cada accesorio cambia el peso, el centro de gravedad y la capacidad de la máquina. Compruebe compatibilidad, presión, caudal, retención y tabla de carga para la configuración real. No use cucharas, horquillas o martillos para funciones no previstas ni improvise puntos de izado.', E'course-1/5h/block-4/slides/audio-4-04-slide-01.png', E'Presentación Cursos Pedro y desarrollo didáctico Inmíner', E'Diapositiva original 81', E'Explicación visual de la parte 4.4: Equipos de trabajo, accesorios y capacidades'),
(4, 4, 2, E'Aplicación segura · Equipos de trabajo, accesorios y capacidades', E'1. Cada accesorio cambia el peso, el centro de gravedad y la capacidad de la máquina\n2. Compruebe compatibilidad, presión, caudal, retención y tabla de carga para la configuración real\n3. No use cucharas, horquillas o martillos para funciones no previstas ni improvise puntos de izado\n\nCriterio de parada: Detenga la operación y comunique cualquier condición que impida trabajar con seguridad.', E'course-1/5h/block-4/slides/audio-4-04-slide-02.png', E'Presentación Cursos Pedro y desarrollo didáctico Inmíner', E'Diapositiva original 82', E'Aplicación segura de la parte 4.4: Equipos de trabajo, accesorios y capacidades'),
(4, 5, 1, E'Neumáticos, cadenas y contacto con el terreno', E'Neumáticos y cadenas condicionan dirección, frenado y estabilidad. Revise presión, cortes, desgaste, barro acumulado y tensión del tren de rodaje. Una máquina pesada puede hundirse aunque la superficie parezca firme; confirme la capacidad portante antes de trabajar sobre rellenos, bordes o plataformas recientes.', E'course-1/5h/block-4/slides/audio-4-05-slide-01.png', E'Presentación Cursos Pedro y desarrollo didáctico Inmíner', E'Diapositiva original 81', E'Explicación visual de la parte 4.5: Neumáticos, cadenas y contacto con el terreno'),
(4, 5, 2, E'Aplicación segura · Neumáticos, cadenas y contacto con el terreno', E'1. Neumáticos y cadenas condicionan dirección, frenado y estabilidad\n2. Revise presión, cortes, desgaste, barro acumulado y tensión del tren de rodaje\n3. Una máquina pesada puede hundirse aunque la superficie parezca firme; confirme la capacidad portante antes de…\n\nCriterio de parada: Detenga la operación y comunique cualquier condición que impida trabajar con seguridad.', E'course-1/5h/block-4/slides/audio-4-05-slide-02.png', E'Presentación Cursos Pedro y desarrollo didáctico Inmíner', E'Diapositiva original 22', E'Aplicación segura de la parte 4.5: Neumáticos, cadenas y contacto con el terreno'),
(4, 6, 1, E'Frenos, dirección y control del movimiento', E'Pruebe freno de servicio, estacionamiento y sistemas de emergencia conforme al manual. La dirección de emergencia permite conservar el control, pero no continuar la producción tras una avería. Si cambia la respuesta, aumenta el recorrido o aparece una alarma, estacione de forma segura y solicite revisión.', E'course-1/5h/block-4/slides/audio-4-06-slide-01.png', E'Presentación Cursos Pedro y desarrollo didáctico Inmíner', E'Diapositiva original 80', E'Explicación visual de la parte 4.6: Frenos, dirección y control del movimiento'),
(4, 6, 2, E'Aplicación segura · Frenos, dirección y control del movimiento', E'1. Pruebe freno de servicio, estacionamiento y sistemas de emergencia conforme al manual\n2. La dirección de emergencia permite conservar el control, pero no continuar la producción tras una avería\n3. Si cambia la respuesta, aumenta el recorrido o aparece una alarma, estacione de forma segura y solicite revisión\n\nCriterio de parada: Si cambia la respuesta, aumenta el recorrido o aparece una alarma, estacione de forma segura y solicite revisión.', E'course-1/5h/block-4/slides/audio-4-06-slide-02.png', E'Presentación Cursos Pedro y desarrollo didáctico Inmíner', E'Diapositiva original 84', E'Aplicación segura de la parte 4.6: Frenos, dirección y control del movimiento'),
(4, 7, 1, E'ROPS, FOPS y cinturón de seguridad', E'Las estructuras ROPS protegen en caso de vuelco y las FOPS frente a la caída de objetos, dentro de sus condiciones de diseño. No deben perforarse, soldarse ni modificarse sin autorización. El cinturón mantiene al operador dentro del espacio protegido y debe utilizarse siempre durante el trabajo.', E'course-1/5h/block-4/slides/audio-4-07-slide-01.png', E'Presentación Cursos Pedro y desarrollo didáctico Inmíner', E'Diapositiva original 84', E'Explicación visual de la parte 4.7: ROPS, FOPS y cinturón de seguridad'),
(4, 7, 2, E'Aplicación segura · ROPS, FOPS y cinturón de seguridad', E'1. Las estructuras ROPS protegen en caso de vuelco y las FOPS frente a la caída de objetos, dentro de sus…\n2. No deben perforarse, soldarse ni modificarse sin autorización\n3. El cinturón mantiene al operador dentro del espacio protegido y debe utilizarse siempre durante el trabajo\n\nCriterio de parada: No deben perforarse, soldarse ni modificarse sin autorización.', E'course-1/5h/block-4/slides/audio-4-07-slide-02.png', E'Presentación Cursos Pedro y desarrollo didáctico Inmíner', E'Diapositiva original 40', E'Aplicación segura de la parte 4.7: ROPS, FOPS y cinturón de seguridad'),
(4, 8, 1, E'Bloqueos, resguardos y prevención del movimiento', E'Los bloqueos mecánicos evitan movimientos por gravedad, pérdida de presión o accionamiento involuntario. Los resguardos separan de correas, ventiladores y elementos giratorios. No anule ninguna protección. Antes de retirar un bloqueo, compruebe que no quedan personas, herramientas ni soportes en la zona.', E'course-1/5h/block-4/slides/audio-4-08-slide-01.png', E'Presentación Cursos Pedro y desarrollo didáctico Inmíner', E'Diapositiva original 83', E'Explicación visual de la parte 4.8: Bloqueos, resguardos y prevención del movimiento'),
(4, 8, 2, E'Aplicación segura · Bloqueos, resguardos y prevención del movimiento', E'1. Los bloqueos mecánicos evitan movimientos por gravedad, pérdida de presión o accionamiento involuntario\n2. Los resguardos separan de correas, ventiladores y elementos giratorios\n3. No anule ninguna protección\n\nCriterio de parada: No anule ninguna protección.', E'course-1/5h/block-4/slides/audio-4-08-slide-02.png', E'Presentación Cursos Pedro y desarrollo didáctico Inmíner', E'Diapositiva original 84', E'Aplicación segura de la parte 4.8: Bloqueos, resguardos y prevención del movimiento'),
(4, 9, 1, E'Instrumentos, alarmas y dispositivos de aviso', E'Manómetros, termómetros y alarmas informan del estado de los sistemas. Conozca la lectura normal y la respuesta exigida para cada aviso. Bocina, cámara, luces y alarma de retroceso ayudan, pero no sustituyen una zona despejada. No tape indicadores ni desconecte alarmas.', E'course-1/5h/block-4/slides/audio-4-09-slide-01.png', E'Presentación Cursos Pedro y desarrollo didáctico Inmíner', E'Diapositiva original 86', E'Explicación visual de la parte 4.9: Instrumentos, alarmas y dispositivos de aviso'),
(4, 9, 2, E'Aplicación segura · Instrumentos, alarmas y dispositivos de aviso', E'1. Manómetros, termómetros y alarmas informan del estado de los sistemas\n2. Conozca la lectura normal y la respuesta exigida para cada aviso\n3. Bocina, cámara, luces y alarma de retroceso ayudan, pero no sustituyen una zona despejada\n\nCriterio de parada: No tape indicadores ni desconecte alarmas.', E'course-1/5h/block-4/slides/audio-4-09-slide-02.png', E'Presentación Cursos Pedro y desarrollo didáctico Inmíner', E'Diapositiva original 87', E'Aplicación segura de la parte 4.9: Instrumentos, alarmas y dispositivos de aviso'),
(4, 10, 1, E'Manual del fabricante y adecuación al Real Decreto 1215/1997', E'El manual define el uso previsto, las capacidades y el mantenimiento de cada modelo. La máquina debe cumplir las disposiciones aplicables del Real Decreto 1215 de 1997 y mantener sus protecciones en buen estado. Si se modifica la configuración o se añade un accesorio, deben evaluarse de nuevo los riesgos.', E'course-1/5h/block-4/slides/audio-4-10-slide-01.png', E'Presentación Cursos Pedro y desarrollo didáctico Inmíner', E'Diapositiva original 40', E'Explicación visual de la parte 4.10: Manual del fabricante y adecuación al Real Decreto 1215/1997'),
(4, 10, 2, E'Aplicación segura · Manual del fabricante y adecuación al Real Decreto 1215/1997', E'1. El manual define el uso previsto, las capacidades y el mantenimiento de cada modelo\n2. La máquina debe cumplir las disposiciones aplicables del Real Decreto 1215 de 1997 y mantener sus protecciones…\n3. Si se modifica la configuración o se añade un accesorio, deben evaluarse de nuevo los riesgos\n\nCriterio de parada: Si se modifica la configuración o se añade un accesorio, deben evaluarse de nuevo los riesgos.', E'course-1/5h/block-4/slides/audio-4-10-slide-02.png', E'Presentación Cursos Pedro y desarrollo didáctico Inmíner', E'Diapositiva original 41', E'Aplicación segura de la parte 4.10: Manual del fabricante y adecuación al Real Decreto 1215/1997'),
(5, 1, 1, E'Vigilancia de frentes, plataformas y taludes', E'Observe el frente, la plataforma y los taludes antes y durante el trabajo. Grietas, agua, bloques sueltos o material recién volado pueden cambiar la estabilidad. Repita la inspección después de lluvias, heladas o voladuras. Ante cualquier duda, retire la máquina fuera del alcance y solicite evaluación.', E'course-1/5h/block-5/slides/audio-5-01-slide-01.png', E'Presentación Cursos Pedro y desarrollo didáctico Inmíner', E'Diapositiva original 85', E'Explicación visual de la parte 5.1: Vigilancia de frentes, plataformas y taludes'),
(5, 1, 2, E'Aplicación segura · Vigilancia de frentes, plataformas y taludes', E'1. Observe el frente, la plataforma y los taludes antes y durante el trabajo\n2. Grietas, agua, bloques sueltos o material recién volado pueden cambiar la estabilidad\n3. Repita la inspección después de lluvias, heladas o voladuras\n\nCriterio de parada: Detenga la operación y comunique cualquier condición que impida trabajar con seguridad.', E'course-1/5h/block-5/slides/audio-5-01-slide-02.png', E'Presentación Cursos Pedro y desarrollo didáctico Inmíner', E'Diapositiva original 88', E'Aplicación segura de la parte 5.1: Vigilancia de frentes, plataformas y taludes'),
(5, 2, 1, E'Pistas, bermas, drenaje y control del polvo', E'Las pistas deben tener anchura, firme, visibilidad y drenaje adecuados. Baches, barro y polvo reducen el control. Las bermas delimitan el borde, pero no son un freno ni garantizan su resistencia. Adapte la velocidad e informe de los deterioros; si la circulación no es segura, detenga su uso.', E'course-1/5h/block-5/slides/audio-5-02-slide-01.png', E'Presentación Cursos Pedro y desarrollo didáctico Inmíner', E'Diapositiva original 88', E'Explicación visual de la parte 5.2: Pistas, bermas, drenaje y control del polvo'),
(5, 2, 2, E'Aplicación segura · Pistas, bermas, drenaje y control del polvo', E'1. Las pistas deben tener anchura, firme, visibilidad y drenaje adecuados\n2. Baches, barro y polvo reducen el control\n3. Las bermas delimitan el borde, pero no son un freno ni garantizan su resistencia\n\nCriterio de parada: Adapte la velocidad e informe de los deterioros; si la circulación no es segura, detenga su uso.', E'course-1/5h/block-5/slides/audio-5-02-slide-02.png', E'Presentación Cursos Pedro y desarrollo didáctico Inmíner', E'Diapositiva original 89', E'Aplicación segura de la parte 5.2: Pistas, bermas, drenaje y control del polvo'),
(5, 3, 1, E'Interferencia entre pala cargadora y camión', E'El punto de espera, la entrada y la salida del camión deben estar definidos. La pala no inicia el ciclo hasta confirmar su posición, evita pasar el cucharón sobre la cabina y distribuye la carga sin golpes. Si aparece una persona o se pierde la comunicación, ambos equipos se detienen.', E'course-1/5h/block-5/slides/audio-5-03-slide-01.png', E'Presentación Cursos Pedro y desarrollo didáctico Inmíner', E'Diapositiva original 90', E'Explicación visual de la parte 5.3: Interferencia entre pala cargadora y camión'),
(5, 3, 2, E'Aplicación segura · Interferencia entre pala cargadora y camión', E'1. El punto de espera, la entrada y la salida del camión deben estar definidos\n2. La pala no inicia el ciclo hasta confirmar su posición, evita pasar el cucharón sobre la cabina y distribuye…\n3. Si aparece una persona o se pierde la comunicación, ambos equipos se detienen\n\nCriterio de parada: Si aparece una persona o se pierde la comunicación, ambos equipos se detienen.', E'course-1/5h/block-5/slides/audio-5-03-slide-02.png', E'Presentación Cursos Pedro y desarrollo didáctico Inmíner', E'Diapositiva original 91', E'Aplicación segura de la parte 5.3: Interferencia entre pala cargadora y camión'),
(5, 4, 1, E'Interferencia entre excavadora y vehículo de transporte', E'Coloque el vehículo fuera del radio de giro y de la posible caída de material. Reduzca el giro y evite pasar la cuchara sobre la cabina. El conductor no moverá el camión hasta recibir la señal. Una sola persona dirige la maniobra y cualquier pérdida de comunicación exige parada inmediata.', E'course-1/5h/block-5/slides/audio-5-04-slide-01.png', E'Presentación Cursos Pedro y desarrollo didáctico Inmíner', E'Diapositiva original 90', E'Explicación visual de la parte 5.4: Interferencia entre excavadora y vehículo de transporte'),
(5, 4, 2, E'Aplicación segura · Interferencia entre excavadora y vehículo de transporte', E'1. Coloque el vehículo fuera del radio de giro y de la posible caída de material\n2. Reduzca el giro y evite pasar la cuchara sobre la cabina\n3. El conductor no moverá el camión hasta recibir la señal\n\nCriterio de parada: Detenga la operación y comunique cualquier condición que impida trabajar con seguridad.', E'course-1/5h/block-5/slides/audio-5-04-slide-02.png', E'Presentación Cursos Pedro y desarrollo didáctico Inmíner', E'Diapositiva original 18', E'Aplicación segura de la parte 5.4: Interferencia entre excavadora y vehículo de transporte'),
(5, 5, 1, E'Personal de tierra, señalistas y comunicaciones', E'Las rutas peatonales y zonas de exclusión deben estar definidas. Para acercarse a una máquina, establezca contacto y espere la confirmación del operador. El señalista debe permanecer visible y usar señales acordadas. Si varias personas dan instrucciones o una orden es ambigua, detenga el trabajo y aclare la maniobra.', E'course-1/5h/block-5/slides/audio-5-05-slide-01.png', E'Presentación Cursos Pedro y desarrollo didáctico Inmíner', E'Diapositiva original 91', E'Explicación visual de la parte 5.5: Personal de tierra, señalistas y comunicaciones'),
(5, 5, 2, E'Aplicación segura · Personal de tierra, señalistas y comunicaciones', E'1. Las rutas peatonales y zonas de exclusión deben estar definidas\n2. Para acercarse a una máquina, establezca contacto y espere la confirmación del operador\n3. El señalista debe permanecer visible y usar señales acordadas\n\nCriterio de parada: Si varias personas dan instrucciones o una orden es ambigua, detenga el trabajo y aclare la maniobra.', E'course-1/5h/block-5/slides/audio-5-05-slide-02.png', E'Presentación Cursos Pedro y desarrollo didáctico Inmíner', E'Diapositiva original 90', E'Aplicación segura de la parte 5.5: Personal de tierra, señalistas y comunicaciones'),
(5, 6, 1, E'Trabajos próximos a líneas eléctricas', E'Una línea aérea puede producir arco sin contacto. Identifique tensión, altura y recorrido, y aplique las distancias y medidas del procedimiento específico. Considere todas las posiciones de pluma y carga. Si hay contacto, permanezca en la cabina salvo peligro inmediato y active el plan de emergencia.', E'course-1/5h/block-5/slides/audio-5-06-slide-01.png', E'Presentación Cursos Pedro y desarrollo didáctico Inmíner', E'Diapositiva original 92', E'Explicación visual de la parte 5.6: Trabajos próximos a líneas eléctricas'),
(5, 6, 2, E'Aplicación segura · Trabajos próximos a líneas eléctricas', E'1. Una línea aérea puede producir arco sin contacto\n2. Identifique tensión, altura y recorrido, y aplique las distancias y medidas del procedimiento específico\n3. Considere todas las posiciones de pluma y carga\n\nCriterio de parada: Si hay contacto, permanezca en la cabina salvo peligro inmediato y active el plan de emergencia.', E'course-1/5h/block-5/slides/audio-5-06-slide-02.png', E'Presentación Cursos Pedro y desarrollo didáctico Inmíner', E'Diapositiva original 92', E'Aplicación segura de la parte 5.6: Trabajos próximos a líneas eléctricas'),
(5, 7, 1, E'Interferencias durante mantenimiento y reparación', E'Antes de reparar, operador y mantenimiento deben acordar quién controla la máquina, qué energías quedan aisladas y cuándo se retira cada bloqueo. Si una prueba requiere movimiento, delimite la zona y designe una persona responsable. Tras la intervención, realice una entrega e inspección funcional.', E'course-1/5h/block-5/slides/audio-5-07-slide-01.png', E'Presentación Cursos Pedro y desarrollo didáctico Inmíner', E'Diapositiva original 39', E'Explicación visual de la parte 5.7: Interferencias durante mantenimiento y reparación'),
(5, 7, 2, E'Aplicación segura · Interferencias durante mantenimiento y reparación', E'1. Antes de reparar, operador y mantenimiento deben acordar quién controla la máquina, qué energías quedan…\n2. Si una prueba requiere movimiento, delimite la zona y designe una persona responsable\n3. Tras la intervención, realice una entrega e inspección funcional\n\nCriterio de parada: Si una prueba requiere movimiento, delimite la zona y designe una persona responsable.', E'course-1/5h/block-5/slides/audio-5-07-slide-02.png', E'Presentación Cursos Pedro y desarrollo didáctico Inmíner', E'Diapositiva original 89', E'Aplicación segura de la parte 5.7: Interferencias durante mantenimiento y reparación'),
(5, 8, 1, E'Incendio, primeros auxilios y conducta PAS', E'Ante un accidente aplique la conducta PAS: proteger, avisar y socorrer. Evite nuevas víctimas, active la emergencia con información precisa y ayude solo dentro de su formación. En un incendio incipiente use el extintor únicamente si dispone de una salida segura y no asume un riesgo adicional.', E'course-1/5h/block-5/slides/audio-5-08-slide-01.png', E'Presentación Cursos Pedro y desarrollo didáctico Inmíner', E'Diapositiva original 49', E'Explicación visual de la parte 5.8: Incendio, primeros auxilios y conducta PAS'),
(5, 8, 2, E'Aplicación segura · Incendio, primeros auxilios y conducta PAS', E'1. Ante un accidente aplique la conducta PAS: proteger, avisar y socorrer\n2. Evite nuevas víctimas, active la emergencia con información precisa y ayude solo dentro de su formación\n3. En un incendio incipiente use el extintor únicamente si dispone de una salida segura y no asume un riesgo…\n\nCriterio de parada: Detenga la operación y comunique cualquier condición que impida trabajar con seguridad.', E'course-1/5h/block-5/slides/audio-5-08-slide-02.png', E'Presentación Cursos Pedro y desarrollo didáctico Inmíner', E'Diapositiva original 50', E'Aplicación segura de la parte 5.8: Incendio, primeros auxilios y conducta PAS'),
(5, 9, 1, E'Plan de emergencia y evacuación', E'Conozca las alarmas, comunicaciones, vías de evacuación y puntos de reunión. Sepa cómo dejar la máquina sin bloquear una pista y cómo informar de su ubicación. No improvise rutas por frentes o zonas de tráfico. Después de un incidente, informe y colabore para evitar que vuelva a repetirse.', E'course-1/5h/block-5/slides/audio-5-09-slide-01.png', E'Presentación Cursos Pedro y desarrollo didáctico Inmíner', E'Diapositiva original 69', E'Explicación visual de la parte 5.9: Plan de emergencia y evacuación'),
(5, 9, 2, E'Aplicación segura · Plan de emergencia y evacuación', E'1. Conozca las alarmas, comunicaciones, vías de evacuación y puntos de reunión\n2. Sepa cómo dejar la máquina sin bloquear una pista y cómo informar de su ubicación\n3. No improvise rutas por frentes o zonas de tráfico\n\nCriterio de parada: No improvise rutas por frentes o zonas de tráfico.', E'course-1/5h/block-5/slides/audio-5-09-slide-02.png', E'Presentación Cursos Pedro y desarrollo didáctico Inmíner', E'Diapositiva original 74', E'Aplicación segura de la parte 5.9: Plan de emergencia y evacuación'),
(5, 10, 1, E'Marco normativo, derechos y obligaciones', E'Esta formación de actualización se encuadra en la ITC 02.1.02 y en la Especificación Técnica 2001-1-08. Para este puesto, la especificación fija una frecuencia máxima obligatoria de dos años. Respete el manual, las disposiciones internas y comunique cualquier situación de riesgo grave.', E'course-1/5h/block-5/slides/audio-5-10-slide-01.png', E'Presentación Cursos Pedro y desarrollo didáctico Inmíner', E'Diapositiva original 93', E'Explicación visual de la parte 5.10: Marco normativo, derechos y obligaciones'),
(5, 10, 2, E'Aplicación segura · Marco normativo, derechos y obligaciones', E'1. Esta formación de actualización se encuadra en la ITC 02.1.02 y en la Especificación Técnica 2001-1-08\n2. Para este puesto, la especificación fija una frecuencia máxima obligatoria de dos años\n3. Respete el manual, las disposiciones internas y comunique cualquier situación de riesgo grave\n\nCriterio de parada: Respete el manual, las disposiciones internas y comunique cualquier situación de riesgo grave.', E'course-1/5h/block-5/slides/audio-5-10-slide-02.png', E'Presentación Cursos Pedro y desarrollo didáctico Inmíner', E'Diapositiva original 2', E'Aplicación segura de la parte 5.10: Marco normativo, derechos y obligaciones');

create temporary table course_one_target_version on commit drop as
select cv.id
from public.course_versions cv
join public.courses c on c.id = cv.course_id
where c.slug = 'operador-maquinaria-arranque-carga-viales'
  and cv.duration_hours = 5
  and cv.status = 'published';

do $$
begin
  if (select count(*) from course_one_target_version) <> 1 then
    raise exception 'Se esperaba una única versión publicada de cinco horas para el Curso 1';
  end if;
  if (select count(*) from course_one_parts) <> 50 then
    raise exception 'El manifiesto debe contener exactamente 50 audios';
  end if;
  if (select count(*) from course_one_slides) <> 100 then
    raise exception 'El manifiesto debe contener exactamente 100 diapositivas';
  end if;
end;
$$;

update public.course_modules module
set title = source.block_title,
    description = 'Bloque formativo con diez apartados de audio, apoyo visual y contenido preventivo.',
    updated_at = now()
from (
  select distinct block_position, block_title from course_one_parts
) source,
course_one_target_version target
where module.course_version_id = target.id
  and module.position = source.block_position
  and module.position between 1 and 5;

do $$
begin
  if (
    select count(*)
    from public.course_modules module
    join course_one_target_version target on target.id = module.course_version_id
    where module.position between 1 and 5
  ) <> 5 then
    raise exception 'No se pudieron resolver exactamente los módulos 1 a 5 del Curso 1';
  end if;

  if exists (
    select 1
    from public.lesson_audio_progress progress
    join public.lesson_audio_segments segment on segment.id = progress.segment_id
    join public.lessons lesson on lesson.id = segment.lesson_id
    join public.course_modules module on module.id = lesson.module_id
    join course_one_target_version target on target.id = module.course_version_id
    where module.position > 5
  ) then
    raise exception 'No se elimina el sexto módulo porque contiene progreso de audio';
  end if;

  if exists (
    select 1
    from public.lesson_progress progress
    join public.lessons lesson on lesson.id = progress.lesson_id
    join public.course_modules module on module.id = lesson.module_id
    join course_one_target_version target on target.id = module.course_version_id
    where module.position > 5
      and (progress.status <> 'locked' or progress.completed_at is not null)
  ) then
    raise exception 'No se elimina el sexto módulo porque contiene progreso real';
  end if;
end;
$$;

delete from public.course_modules module
using course_one_target_version target
where module.course_version_id = target.id
  and module.position > 5;

create temporary table course_one_lessons on commit drop as
select module.position as block_position, lesson.id as lesson_id
from public.course_modules module
join course_one_target_version target on target.id = module.course_version_id
join public.lessons lesson on lesson.module_id = module.id
where module.position between 1 and 5
  and lesson.position = 1;

do $$
begin
  if (select count(*) from course_one_lessons) <> 5 then
    raise exception 'Se esperaba una lección principal por cada uno de los cinco bloques';
  end if;
end;
$$;

update public.lessons lesson
set title = format('Bloque %s · %s', part.block_position, part.block_title),
    summary = 'Diez apartados secuenciales con audio, dos diapositivas y explicación preventiva.',
    duration_minutes = 60,
    active = true,
    updated_at = now()
from course_one_lessons target_lesson
join (
  select distinct block_position, block_title from course_one_parts
) part using (block_position)
where lesson.id = target_lesson.lesson_id;

delete from public.lesson_audio_segments segment
using course_one_lessons target_lesson
where segment.lesson_id = target_lesson.lesson_id
  and not exists (
    select 1 from course_one_parts part
    where part.block_position = target_lesson.block_position
      and part.segment_position = segment.position
  );

insert into public.lesson_audio_segments (
  lesson_id,
  position,
  title,
  narration_text,
  audio_storage_path,
  audio_external_url,
  duration_seconds,
  published
)
select
  target_lesson.lesson_id,
  part.segment_position,
  part.title,
  part.narration,
  replace(part.audio_path_template, '{courseVersionId}', target.id::text),
  null,
  part.duration_seconds,
  true
from course_one_parts part
join course_one_lessons target_lesson using (block_position)
cross join course_one_target_version target
on conflict (lesson_id, position) do update
set title = excluded.title,
    narration_text = excluded.narration_text,
    audio_storage_path = excluded.audio_storage_path,
    audio_external_url = null,
    duration_seconds = excluded.duration_seconds,
    published = true,
    updated_at = now();

create temporary table course_one_segments on commit drop as
select
  target_lesson.block_position,
  segment.position as segment_position,
  segment.id as segment_id
from course_one_lessons target_lesson
join public.lesson_audio_segments segment on segment.lesson_id = target_lesson.lesson_id
where segment.position between 1 and 10;

delete from public.lesson_segment_slides slide
using course_one_segments target_segment
where slide.segment_id = target_segment.segment_id;

insert into public.lesson_segment_slides (
  segment_id,
  position,
  title,
  body,
  image_storage_path,
  image_external_url,
  source_label,
  source_page,
  alt_text
)
select
  target_segment.segment_id,
  slide.slide_position,
  slide.title,
  slide.body,
  slide.storage_path,
  null,
  slide.source_label,
  slide.source_page,
  slide.alt_text
from course_one_slides slide
join course_one_segments target_segment
  on target_segment.block_position = slide.block_position
 and target_segment.segment_position = slide.segment_position;

insert into public.lesson_segment_notes (
  segment_id,
  summary,
  key_points,
  stop_criterion,
  source_label,
  source_pages,
  approved
)
select
  target_segment.segment_id,
  part.explanation,
  part.key_points,
  part.stop_criterion,
  part.source_label,
  part.source_pages,
  true
from course_one_parts part
join course_one_segments target_segment
  on target_segment.block_position = part.block_position
 and target_segment.segment_position = part.segment_position
on conflict (segment_id) do update
set summary = excluded.summary,
    key_points = excluded.key_points,
    stop_criterion = excluded.stop_criterion,
    source_label = excluded.source_label,
    source_pages = excluded.source_pages,
    approved = true,
    updated_at = now();

delete from public.lesson_resources resource
using course_one_lessons target_lesson
where resource.lesson_id = target_lesson.lesson_id
  and resource.kind = 'pdf'
  and (
    resource.title = 'Manual oficial del operador de maquinaria de arranque, carga y viales'
    or resource.external_url like '%Operador_maquinaria_arranque_carga_viales.pdf%'
    or resource.storage_path like '%/resources/manual-operador-maquinaria-arranque-ET-2001-1-08.pdf'
  );

insert into public.lesson_resources (
  lesson_id,
  kind,
  title,
  storage_path,
  external_url,
  mime_type,
  size_bytes,
  downloadable,
  required,
  position
)
select
  target_lesson.lesson_id,
  'pdf'::public.resource_kind,
  'Manual oficial del operador de maquinaria de arranque, carga y viales',
  target.id::text || '/resources/manual-operador-maquinaria-arranque-ET-2001-1-08.pdf',
  null,
  'application/pdf',
  16817673,
  false,
  false,
  1
from course_one_lessons target_lesson
cross join course_one_target_version target;

drop policy if exists course_materials_enrolled_read on storage.objects;
create policy course_materials_enrolled_read
on storage.objects
for select
to authenticated
using (
  bucket_id = 'course-materials'
  and (
    (
      (storage.foldername(name))[1] ~ '^[0-9a-fA-F-]{36}$'
      and (
        (select app_private.current_user_is_enrolled(((storage.foldername(name))[1])::uuid))
        or (select app_private.current_user_has_role(array[
          'tutor'::public.app_role,
          'administrador'::public.app_role,
          'superadministrador'::public.app_role
        ]))
      )
    )
    or (
      name like 'course-1/5h/%'
      and (
        exists (
          select 1
          from public.course_versions cv
          join public.courses c on c.id = cv.course_id
          where c.slug = 'operador-maquinaria-arranque-carga-viales'
            and cv.duration_hours = 5
            and cv.status = 'published'
            and (select app_private.current_user_is_enrolled(cv.id))
        )
        or (select app_private.current_user_has_role(array[
          'tutor'::public.app_role,
          'administrador'::public.app_role,
          'superadministrador'::public.app_role
        ]))
      )
    )
  )
);

do $$
declare
  target_id uuid;
begin
  select id into target_id from course_one_target_version;

  if (
    select count(*) from storage.objects object
    join course_one_slides slide on slide.storage_path = object.name
    where object.bucket_id = 'course-materials'
      and coalesce((object.metadata ->> 'size')::bigint, 0) > 10000
  ) <> 100 then
    raise exception 'Los 100 PNG privados no están disponibles o tienen un tamaño inválido';
  end if;

  if (
    select count(*) from storage.objects object
    join course_one_parts part
      on object.name = replace(part.audio_path_template, '{courseVersionId}', target_id::text)
    where object.bucket_id = 'course-materials'
      and coalesce((object.metadata ->> 'size')::bigint, 0) = part.size_bytes
  ) <> 50 then
    raise exception 'Los 50 audios privados no están disponibles con el tamaño validado';
  end if;

  if not exists (
    select 1 from storage.objects object
    where object.bucket_id = 'course-materials'
      and object.name = target_id::text || '/resources/manual-operador-maquinaria-arranque-ET-2001-1-08.pdf'
      and coalesce((object.metadata ->> 'size')::bigint, 0) = 16817673
  ) then
    raise exception 'El manual PDF privado no está disponible con el tamaño validado';
  end if;

  if (select count(*) from course_one_segments) <> 50 then
    raise exception 'El Curso 1 no contiene exactamente 50 segmentos';
  end if;
  if exists (
    select 1 from course_one_segments segment
    left join public.lesson_segment_slides slide on slide.segment_id = segment.segment_id
    group by segment.segment_id having count(slide.id) <> 2
  ) then
    raise exception 'Cada audio del Curso 1 debe tener exactamente dos diapositivas';
  end if;
  if (
    select count(*) from public.lesson_segment_notes note
    join course_one_segments segment on segment.segment_id = note.segment_id
    where note.approved
      and cardinality(note.key_points) = 3
      and char_length(note.stop_criterion) >= 10
  ) <> 50 then
    raise exception 'Los 50 audios deben tener explicación, tres puntos y criterio de parada';
  end if;
  if (
    select count(*) from public.lesson_resources resource
    join course_one_lessons lesson on lesson.lesson_id = resource.lesson_id
    where resource.kind = 'pdf'
      and resource.storage_path = target_id::text || '/resources/manual-operador-maquinaria-arranque-ET-2001-1-08.pdf'
  ) <> 5 then
    raise exception 'El manual PDF debe estar vinculado a los cinco bloques';
  end if;
end;
$$;

commit;
